import type { Answer } from "@/lib/types";
import { U } from "./build";

// ANSWER KEY — motion in gravitational fields. NO "server-only" import here (the validator reads
// it); only re-exported via content/answers/index.ts, which is server-only.
// Every answer was worked independently and checked against the school's key where one could be
// found (see resources/topic006/06-transcription-log.md).

const m = (n: number, correctText: string, why: string): [string, Answer] => [
  `${U}.m${String(n).padStart(3, "0")}`,
  { correctText, rubric: [why] },
];

const s = (n: number, modelAnswer: string, rubric: string[]): [string, Answer] => [
  `${U}.s${String(n).padStart(3, "0")}`,
  { modelAnswer, rubric },
];

export const gravitationAnswers: Array<[string, Answer]> = [
  m(1, "5.41 × 10²⁸ kg", "From r³/T² = GM/4π²: M = 4π²r³/(GT²) = 4π²(3.80 × 10¹⁰)³ / (6.67 × 10⁻¹¹ × (2.45 × 10⁷)²) ≈ 5.41 × 10²⁸ kg."),
  m(2, "gravitational potential energy", "The planet is moving towards the star, so its distance r is decreasing and U = −GMm/r becomes more negative (decreases). Its kinetic energy and acceleration increase, and its total energy is constant."),
  m(3, "√(5³)", "By Kepler's third law T² ∝ r³, so T_X/T_Y = (r_X/r_Y)^(3/2) = 5^(3/2) = √(5³)."),
  m(4, "−2.8 × 10⁹ J", "From the graph, U ≈ −2.9 × 10⁹ J at 14 000 km and U ≈ −5.8 × 10⁹ J at 4000 km, so ΔU = U_final − U_initial ≈ −2.8 × 10⁹ J (it decreases as the satellite moves closer)."),
  m(5, "8 g", "g = GM/r². Doubling M doubles g, and halving r multiplies g by 4, so g_Y = 2 × 4 × g = 8g."),
  m(6, "2465", "Kepler's third law for the same star: T_B = T_A (r_B/r_A)^(3/2) = 15 × (6 × 10⁹ / 2 × 10⁸)^(3/2) = 15 × 30^(3/2) ≈ 2465 ooshwucks. Planet A's mass is not needed."),
  m(7, "35,930 km", "r³ = GMT²/4π² with T = 24 h gives r ≈ 4.23 × 10⁷ m (42 300 km); the altitude is r minus Earth's radius (6371 km) ≈ 35 930 km."),
  m(8, "Diagram A", "With no gravitational force there is no net force, so by Newton's first law the satellite moves in a straight line along the tangent to its orbit at X."),
  m(9, "Gravity is the only force acting on him.", "The astronaut and the station are both in free fall around Earth, with gravity the only force acting; there is no normal force, so he feels weightless. Gravity is still about 90% of its surface value there."),
  m(10, "Kinetic energy 40 000 J; gravitational potential energy −80 000 J; total energy −40 000 J", "For a circular orbit K = GMm/2r, U = −GMm/r and E = K + U = −GMm/2r, so U = −2K and E = −K: 40 000 J, −80 000 J and −40 000 J."),
  m(11, "Bohr: planet mass 5 × 10²⁴ kg, planet radius 9500 km", "v_esc = √(2GM/r), so the lowest escape velocity has the smallest M/r. Bohr: 5 × 10²⁴ / 9500 is the smallest ratio."),
  m(12, "F/4", "F = GMm/r², an inverse-square law: doubling the distance divides the force by 2² = 4."),
  m(13, "The period of one revolution of the satellite is equal to the time taken for one spin of the planet on its axis.", "A geostationary satellite stays above the same point, so its orbital period must equal the planet's rotation period (and it orbits above the equator in the direction of rotation)."),
  m(14, "T_A = 15 T_B", "T² ∝ r³, so T_A/T_B = 6^(3/2) ≈ 14.7, i.e. about 15."),
  m(15, "When the moon reaches the perigee, its gravitational potential energy will be at a minimum and its kinetic energy will be at a maximum. It will move at a high velocity.", "At perigee the Moon is closest to Earth, so U = −GMm/r is lowest; total energy is conserved, so kinetic energy and speed are greatest there."),
  m(16, "For an identical planet orbiting a different star", "k = 4π²/GM depends only on the mass M of the central body, so k changes only when the star changes."),
  m(17, "Increase by 105 m/s", "v = √(GM/r). At 850 km, r = 7.221 × 10⁶ m and v ≈ 7445 m/s; at 650 km, r = 7.021 × 10⁶ m and v ≈ 7550 m/s. The speed must increase by about 105 m/s."),
  m(18, "The acceleration due to gravity experienced by Ursae Majoris B is 6.3 times greater than that due to gravity experienced by Ursae Majoris C.", "a = 4π²r/T²: B gives ≈ 13.9 m s⁻² and C gives ≈ 2.2 m s⁻², so B's is about 6.3 times C's (equivalently a ∝ 1/r², and (1.56 × 10⁹ / 6.2 × 10⁸)² ≈ 6.3)."),
  m(19, "E_total = U / 2", "In a circular orbit U = −GMm/r and K = GMm/2r, so E = K + U = −GMm/2r = U/2 (= −K)."),
  m(20, "X : Y = 1 : 1", "Orbital speed v = √(GM/r) depends on the central mass and the orbital radius, not on the satellite's mass, so the speeds are equal."),
  m(21, "It would decrease by a factor of 2.", "U = −GMm/r. Moving Y from 2r to r changes U from −GMm/2r to −GMm/r: twice as large in size but negative, so U decreases (becomes twice as negative)."),
  m(22, "v_esc = √2 v_orb; E = U / 2", "v_orb = √(GM/r) and v_esc = √(2GM/r), so v_esc = √2 v_orb. In a circular orbit K = GMm/2r and U = −GMm/r, so E = K + U = −GMm/2r = U/2 (and K = −U/2)."),
  m(23, "Work done on satellite A from X to Y: non-zero; work done on satellite B from P to Q: zero", "On the ellipse the distance from Earth changes between X and Y, so U and K change: gravity does non-zero work. On the circle gravity is always perpendicular to the velocity and r is constant, so it does no work."),
  m(24, "U_A = 2U_B; v_A = √2 v_B", "Orbital radii are R + R = 2R and R + 3R = 4R. U = −GMm/r, so U_A = −GMm/2R = 2 × (−GMm/4R) = 2U_B. v = √(GM/r), so v_A/v_B = √(4R/2R) = √2."),
  m(25, "(9/7) R", "With v = ¾ v_esc, K = (9/16)(GMm/R). Energy conservation: (9/16)GMm/R − GMm/R = −GMm/r, so r = (16/7)R. The height above the surface is r − R = (9/7)R."),
  m(26, "Diagram A", "Slowing at X leaves too little speed for a circular orbit there, so X becomes the farthest point (apogee) of a smaller elliptical orbit that still passes through X, with the planet at a focus."),
  m(27, "6 × 10²³ kg", "g = GM/r², so M = gr²/G. From the graph g = 2.5 m s⁻² at r = 4 × 10⁶ m: M = 2.5 × (4 × 10⁶)² / 6.67 × 10⁻¹¹ ≈ 6 × 10²³ kg."),
  m(28, "2.5 × 10¹⁰ J", "Orbital energy E = −GMm/2r. ΔE = (GMm/2)(1/r₁ − 1/r₂) = (6.67 × 10⁻¹¹ × 6.0 × 10²⁴ × 1000 / 2)(1/6.8 × 10⁶ − 1/4.2 × 10⁷) ≈ 2.5 × 10¹⁰ J."),
  m(29, "Formula: g = GM / R²; direction: towards the centre", "The acceleration due to gravity at the surface is g = GM/R² (independent of the object's mass m), directed towards the centre of the Earth. F = GMm/R² is the force, not the acceleration."),
  m(30, "3.3 × 10⁶ m", "Kepler's third law: r₂ = r₁ (T₂/T₁)^(2/3) = 2.3 × 10⁶ × (1.3 × 10⁵ / 7.6 × 10⁴)^(2/3) ≈ 3.3 × 10⁶ m."),
  m(31, "1.0 × 10¹⁰ J", "ΔU = GMm(1/r₁ − 1/r₂) = 6.67 × 10⁻¹¹ × 6.0 × 10²⁴ × 500 × (1/1.0 × 10⁷ − 1/2.0 × 10⁷) ≈ 1.0 × 10¹⁰ J (an increase)."),
  m(32, "Diagram A", "The only force on the satellite is gravity, which points to the centre of the Earth, so its acceleration points straight at Earth's centre wherever it is on the orbit."),
  m(33, "Speed: v_D > v_A > v_C > v_B; total mechanical energy: E_A = E_B = E_C = E_D", "The comet moves fastest closest to the Sun (D) and slowest farthest away (B); A is closer than C, so v_A > v_C. With only gravity acting, total mechanical energy is conserved, so it is the same everywhere."),
  m(34, "The total orbital energy of Neptune has the same magnitude as its kinetic energy.", "Kepler's laws are: elliptical orbits with the Sun at a focus; equal areas in equal times (faster when closer); T²/r³ is the same for all planets of the Sun. The energy statement is true for circular orbits but is not one of Kepler's laws."),
  m(35, "Graph A", "For an orbit K = −E and U = 2E. With E = −6, −3.3, −1.8, −1.0, −0.7, K = 6, 3.3, 1.8, 1.0, 0.7 and U = −12, −6.6, −3.6, −2.0, −1.4, which is graph A."),
  m(36, "0.22 : 1", "g = GM/r², so g_X/g_Y = (2)/(3²) = 2/9 ≈ 0.22."),
  m(37, "The acceleration of the object equals the gravitational acceleration of the Earth.", "Escape velocity is the launch speed for which K = |U| at the surface, so the object just reaches an infinite distance, where the gravitational force (and U) falls to zero. The object's acceleration matching g is not part of the definition."),
  m(38, "0.354", "Orbital radii: 6371 + 629 = 7000 km and 6371 + 7629 = 14 000 km. T ∝ r^(3/2), so T_A/T_B = (7000/14 000)^(3/2) = 0.5^1.5 ≈ 0.354."),
  m(39, "continuously monitor the same location on Earth.", "A geostationary satellite has a 24-hour period above the equator, so it stays over the same point on Earth. Being much farther away, it sees less detail and cannot see the whole Earth."),
  m(40, "v_A:v_B = 2:1", "T² ∝ r³, so r_A/r_B = (1/8)^(2/3) = 1/4. v = √(GM/r), so v_A/v_B = √4 = 2."),
  m(41, "1 : √2", "Orbital speed v = √(GM/r) does not depend on the satellite's mass. r_X = 2r_Y, so v_X/v_Y = √(r_Y/r_X) = 1/√2."),
  m(42, "1.35 × 10²³ kg", "g = GM/r², so M = gr²/G = 1.35 × (2.575 × 10⁶)² / 6.67 × 10⁻¹¹ ≈ 1.34 × 10²³ kg, closest to 1.35 × 10²³ kg."),
  m(43, "Lower speed; longer orbital period; greater orbital radius; less centripetal force", "A geostationary orbit (r ≈ 42 000 km) is much larger than a low-Earth orbit. Larger r gives lower v = √(GM/r), a longer period (24 h) and a smaller gravitational (centripetal) force GMm/r²."),
  m(44, "Tri would take 8 times longer than Centaur to make a full orbit of the star", "T² ∝ r³. Tri's radius is 4 times Centaur's, so T_Tri/T_Centaur = 4^(3/2) = 8."),
  m(45, "1.5 m s⁻²", "g = GM/r² = 6.67 × 10⁻¹¹ × 1.5 × 10²³ / (2.6 × 10⁶)² ≈ 1.5 m s⁻²."),
  m(46, "Kinetic energy: decrease; gravitational potential energy: increase", "K = GMm/2r decreases as r increases, and U = −GMm/r becomes less negative, so it increases."),
  m(47, "The mass of the satellite.", "v = √(GM/r): the orbital velocity depends on the planet's mass (and so its gravitational pull) and the orbital radius (altitude), but not on the satellite's own mass."),
  m(48, "4r / 5", "In a circular orbit K = GMm/2r, so K ∝ 1/r. K becomes 1.25K, so r becomes r/1.25 = 4r/5."),
  m(49, "The change in gravitational potential energy between points X and Y.", "Gravity is a conservative force: the work it does depends only on the start and end points, not the path, and equals the change in gravitational potential energy (W = −ΔU: equal in size, opposite in sign). The winding path shows the spacecraft is under power, so the change in kinetic energy is not set by gravity alone."),
  m(50, "The mass of the object being projected.", "v_esc = √(2GM/r) depends on G, the planet's mass and its radius, but not on the mass of the object being projected."),
  m(51, "The mass is at the top of its trajectory: B; the mass is falling towards the Earth: C", "At the top it is momentarily at rest, so K = 0 and E = U: point B on the curve. While falling it has K > 0, so E is above the curve, but it is still bound (it did not escape), so E < 0: point C."),
  m(52, "3 : 4", "g = GM/r², so g_F/g_U = 12/4² = 12/16 = 3/4."),
  m(53, "3:2", "Measured from the scale drawing, X is 2 Earth radii and Y is 3 Earth radii from Earth's centre. In a circular orbit K = GMm/2r ∝ 1/r, so K_X/K_Y = 3/2."),
  m(54, "1.61 × 10²² N", "The gravitational force supplies Ganymede's centripetal force: F = mv²/r = 1.48 × 10²³ × (1.08 × 10⁴)² / 1.07 × 10⁹ ≈ 1.61 × 10²² N. By Newton's third law this is also the force of Ganymede on Jupiter."),
  m(55, "3.46 × 10⁸ m", "At distance d from Earth: GM_E/d² = GM_M/(D − d)² with D = 3.84 × 10⁸ m, so d = D / (1 + √(M_M/M_E)) = 3.84 × 10⁸ / (1 + 0.111) ≈ 3.46 × 10⁸ m. The Earth's orbital radius around the Sun is not needed."),
  m(56, "V/2", "v = √(GM/r), so multiplying r by 4 divides v by √4 = 2."),
  m(57, "−1.00 × 10¹¹ J", "r = 6.371 × 10⁶ + 1.88 × 10⁷ = 2.517 × 10⁷ m. U = −GMm/r = −6.67 × 10⁻¹¹ × 6.0 × 10²⁴ × 6.30 × 10³ / 2.517 × 10⁷ ≈ −1.00 × 10¹¹ J."),
  m(58, "1.5", "Kepler's third law: T² ∝ r³, so T ∝ r^(3/2) = r^1.5."),
  m(59, "Change in potential energy: decreases; change in kinetic energy: increases", "Moving closer makes U = −GMm/r more negative (it decreases), and the orbital speed √(GM/r) increases, so the kinetic energy increases."),
  m(60, "4", "F = mv²/r. F₁ = mv²/r and F₂ = m(v²/2)/(2r) = mv²/4r, so F₁/F₂ = 4."),
  m(61, "25 N kg⁻¹.", "Gravitational field strength is the force per unit mass, which equals the free-fall acceleration: 25 m s⁻² = 25 N kg⁻¹. The sphere's mass is not needed."),
  m(62, "M and r.", "v_esc = √(2GM/r): it depends on G, the planet's mass M and its radius r, not on the object's mass m."),
  m(63, "Inverse square of the distance from the centre of the planet. Gradient = GM", "g = GM/r² = GM × (1/r²), so plotting g against 1/r² gives a straight line through the origin with gradient GM."),
  m(64, "Short orbital period: Near Earth Orbit; large altitude: Geostationary Orbit; used for mapping surface terrain: Near Earth Orbit", "Low (near-Earth) orbits have short periods (about 90 min) and are close enough for detailed mapping; geostationary orbits are at a large altitude (about 36 000 km)."),
  m(65, "11.3 N kg⁻¹", "g = GM/r² = 6.67 × 10⁻¹¹ × 1.024 × 10²⁶ / (2.46 × 10⁷)² ≈ 11.3 N kg⁻¹."),
  m(66, "Greater orbital speed: S₁; greater gravitational potential energy: S₂", "The LEO satellite S₁ has the smaller radius, so the larger speed √(GM/r). U = −GMm/r is less negative (greater) for the larger GEO orbit, so S₂ has more potential energy."),
  m(67, "It will leave the Earth and travel to outer space.", "Spacecraft 1's speed v is the orbital speed near the surface, √(GM/r). Escape speed there is √2 v ≈ 1.41v, so a launch speed of 2v exceeds escape speed and Spacecraft 2 escapes."),
  m(68, "Orbital velocity of P compared to orbital velocity of Q: greater; escape velocity of P compared to escape velocity of Q: greater", "Both depend on the planet's mass and the orbital radius, not the satellite's mass: v_orb = √(GM/r) and v_esc = √(2GM/r). P's orbit is smaller, so both are greater for P."),
  m(69, "The planes in which the planets move about the Sun is parallel to the plane of the equator of the Sun.", "Kepler's laws are: elliptical orbits with the Sun at a focus; equal areas swept in equal times; T²/r³ constant. Nothing is said about orbital planes and the Sun's equator."),
  m(70, "The change in the gravitational potential energy", "The area under a force–distance graph is the work done by the force, ∫F dr = GMm(1/r_X − 1/r_Y), which equals the change in gravitational potential energy between X and Y."),
  m(71, "8.0", "F = GMm/r². F_Mercury/F_Mars = (m/r²) ÷ (2m/(4r)²) = 16/2 = 8."),
  m(72, "GMm / 2r", "ΔU = U_final − U_initial = −GMm/2r − (−GMm/r) = +GMm/2r (it increases)."),
  m(73, "2.44 N kg⁻¹", "g ∝ 1/r², so at 2R the field is 9.76/4 = 2.44 N kg⁻¹."),
  m(74, "r/4", "v = √(GM/r), so r ∝ 1/v². Doubling v divides r by 4."),
  m(75, "1:1", "By Newton's third law the two gravitational forces form an action–reaction pair: equal in size and opposite in direction, whatever the masses."),
  m(76, "170 minutes", "T ∝ r^(3/2), so doubling r multiplies T by 2^1.5 ≈ 2.83: 60 × 2.83 ≈ 170 minutes."),
  m(77, "the velocity needed to provide an initial kinetic energy such that total mechanical energy is zero.", "Escape velocity is the launch speed at which K + U = 0, so the object just reaches infinite distance with zero speed. It is not about orbiting or leaving the atmosphere."),
  m(78, "4.34 × 10⁴ N", "The gravitational force provides the centripetal force: F = 4π²mr/T² = 4π² × 3500 × 9.17 × 10⁶ / (5400)² ≈ 4.34 × 10⁴ N."),
  m(79, "421 909 km", "Kepler's third law: r_Io = r_Europa (T_Io/T_Europa)^(2/3) = 671 000 × (1.77/3.55)^(2/3) ≈ 421 900 km."),
  m(80, "2.14 km s⁻¹", "v = √(GM/r), so v ∝ 1/√r for the same planet: v_Phobos = 1.35 × √(2.35 × 10⁷ / 9.38 × 10⁶) ≈ 2.14 km s⁻¹. The moons' masses are not needed."),
  m(81, "Work done on Satellite A from R to S: zero; work done on Satellite B from P to Q: non-zero", "On the circular orbit gravity is always perpendicular to the velocity and r stays the same, so it does no work. On the ellipse Q is farther from Earth than P, so U increases and K decreases: gravity does (negative) work."),
  m(82, "Double the mass of both objects.", "F = Gm₁m₂/r². Doubling both masses multiplies F by 4; doubling one mass doubles it; doubling the distance or halving both masses makes it smaller."),
  m(83, "Kinetic energy increases, potential energy decreases.", "Moving closer, U = −GMm/r becomes more negative (decreases). Total energy is conserved, so kinetic energy increases by the same amount."),
  m(84, "8T", "T² ∝ r³, so T ∝ r^(3/2): 4^(3/2) = 8, giving 8T."),
  m(85, "5.0 km/s", "r = 6378 + 25 480 = 31 858 km = 3.19 × 10⁷ m. v_esc = √(2GM/r) = √(2 × 6.67 × 10⁻¹¹ × 6.0 × 10²⁴ / 3.19 × 10⁷) ≈ 5.0 × 10³ m s⁻¹."),
  m(86, "The star is located at C and the planet takes more time to travel P to Q than it does for R to S.", "A and C are the foci, so the star could be at C. By Kepler's second law equal areas take equal times: from C, the line to the planet sweeps a much larger area going P to Q (the far end) than R to S (the near end), so P to Q takes longer."),
  m(87, "3.6 × 10²² N", "F = GMm/r² = 6.67 × 10⁻¹¹ × 2.0 × 10³⁰ × 6.0 × 10²⁴ / (1.5 × 10¹¹)² ≈ 3.6 × 10²² N, using Earth's mass from the data sheet."),
  m(88, "T/8", "T ∝ r^(3/2), so T_B = T × (1/4)^(3/2) = T/8."),
  m(89, "Low Earth Orbit: higher orbital velocity; Geostationary Orbit: smaller acceleration", "A low orbit has the smaller radius, so the higher speed √(GM/r). The geostationary orbit is far larger, so its acceleration GM/r² is smaller. The other pairs each contain a false statement."),
  m(90, "3.6 days.", "T ∝ r^(3/2): T_Europa = 7.2 × 0.63^1.5 ≈ 7.2 × 0.50 = 3.6 days."),

  // ---- Short answer -------------------------------------------------------------------
  s(1, "g = GM/r², so r = √(GM/g) = √(6.67 × 10⁻¹¹ × 6.0 × 10²⁴ / 2.45) ≈ 1.28 × 10⁷ m (from Earth's centre).", [
    "Uses g = GM/r² and rearranges for r.",
    "Correct substitution giving r ≈ 1.28 × 10⁷ m.",
  ]),
  s(2, "Force: F = GMm/r², so at the same radius satellite II feels twice the gravitational force of satellite I. Motion: the gravitational force is the centripetal force, GMm/r² = mv²/r, so v = √(GM/r) and T = 2π√(r³/GM); the satellite's mass cancels, so both have the same orbital speed, period and acceleration (g = GM/r²). Energy: K = GMm/2r, U = −GMm/r and E = −GMm/2r are all proportional to m, so satellite II has twice the kinetic, potential (twice as negative) and total energy of satellite I.", [
    "Force: F = GMm/r², so the force on II is twice that on I.",
    "Motion: equating gravity with centripetal force shows v = √(GM/r) (and T) is independent of the satellite's mass, so speed and period are the same.",
    "States that both have the same acceleration (or uses the equations to justify the comparison).",
    "Energy: K, U and total energy are all proportional to m, so II has twice the magnitude of each.",
  ]),
  s(3, "(a) The gravitational force provides the centripetal force: F_g = m_s v²/r. For a circular orbit v = 2πr/T, so F_g = m_s(2πr/T)²/r = 4π²m_s r/T². Rearranging: r = T²F_g / (4π²m_s).\n(b) r = (2.16 × 10⁴)² × 80 / (4π² × 50) ≈ 1.89 × 10⁷ m.\n(c) v = 2πr/T = 2π × 1.89 × 10⁷ / 2.16 × 10⁴ ≈ 5.50 × 10³ m s⁻¹, so K = ½mv² = ½ × 50 × (5.50 × 10³)² ≈ 7.6 × 10⁸ J. (Equivalently K = ½F_g r.)", [
    "(a) States that the gravitational force provides the centripetal force: F_g = m_s v²/r.",
    "(a) Substitutes v = 2πr/T.",
    "(a) Rearranges correctly to r = T²F_g / (4π²m_s).",
    "(b) r ≈ 1.89 × 10⁷ m.",
    "(c) Uses K = ½mv² (or K = ½F_g r).",
    "(c) Finds the orbital speed v = 2πr/T ≈ 5.5 × 10³ m s⁻¹.",
    "(c) K ≈ 7.6 × 10⁸ J.",
  ]),
  s(4, "(a) ½mv² = GMm/r, so v_esc = √(2GM/r).\n(b) v = √(2 × 6.67 × 10⁻¹¹ × 7.35 × 10²² / 1.74 × 10⁶) ≈ 2.37 × 10³ m s⁻¹ (the golf ball's mass does not matter).\n(c) Energy is conserved: ½v₁² − GM/R = ½v₂² − GM/(R + h). With R = 1.74 × 10⁶ m and R + h = 1.77 × 10⁶ m: ½v₂² = ½(1200)² − GM/R + GM/(R + h) ≈ 7.2 × 10⁵ − 2.817 × 10⁶ + 2.770 × 10⁶ ≈ 6.72 × 10⁵ J kg⁻¹, so v₂ ≈ 1.16 × 10³ m s⁻¹.\n(d) v = √(GM/r) = √(6.67 × 10⁻¹¹ × 7.35 × 10²² / 1.77 × 10⁶) ≈ 1.66 × 10³ m s⁻¹.", [
    "(a) Sets ½mv² = GMm/r.",
    "(a) Rearranges to v_esc = √(2GM/r).",
    "(b) v_esc ≈ 2.37 × 10³ m s⁻¹.",
    "(c) Uses conservation of energy with U = −GMm/r at both heights (not mgh).",
    "(c) Correct radii (1.74 × 10⁶ m and 1.77 × 10⁶ m) substituted.",
    "(c) v ≈ 1.16 × 10³ m s⁻¹.",
    "(d) Uses v = √(GM/r) with r = 1.77 × 10⁶ m.",
    "(d) v ≈ 1.66 × 10³ m s⁻¹.",
  ]),
  s(5, "r = 6.371 × 10⁶ + 7.80 × 10⁵ = 7.151 × 10⁶ m.\n(a) F = GMm/r² = 6.67 × 10⁻¹¹ × 6.0 × 10²⁴ × 1500 / (7.151 × 10⁶)² ≈ 1.17 × 10⁴ N.\n(b) v = √(GM/r) = √(6.67 × 10⁻¹¹ × 6.0 × 10²⁴ / 7.151 × 10⁶) ≈ 7.48 × 10³ m s⁻¹.\n(c) New radius r₂ = 7.084 × 10⁶ m. ΔU = −GMm/r₂ − (−GMm/r₁) = GMm(1/r₁ − 1/r₂) ≈ −7.9 × 10⁸ J (a decrease of about 7.9 × 10⁸ J).", [
    "(a) Uses F = GMm/r² with r = R_E + altitude.",
    "(a) F ≈ 1.17 × 10⁴ N.",
    "(b) Uses v = √(GM/r) (or F = mv²/r).",
    "(b) v ≈ 7.48 × 10³ m s⁻¹.",
    "(c) Uses U = −GMm/r at both radii (r₂ = 7.084 × 10⁶ m).",
    "(c) ΔU ≈ −7.9 × 10⁸ J (a decrease).",
  ]),
  s(6, "(a) From Kepler's third law r³/T² = GM/4π², so the gradient of r³ against T² is GM/4π². Gradient ≈ (665 × 10²⁵) / (20.8 × 10¹¹) ≈ 3.2 × 10¹⁵ m³ s⁻². M = 4π² × gradient / G = 4π² × 3.2 × 10¹⁵ / 6.67 × 10⁻¹¹ ≈ 1.9 × 10²⁷ kg.\n(b)(i) R = 2 × 6.371 × 10⁶ = 1.27 × 10⁷ m. v_esc = √(2GM/R) = √(2 × 6.67 × 10⁻¹¹ × 5.7 × 10²⁶ / 1.27 × 10⁷) ≈ 7.7 × 10⁴ m s⁻¹.\n(b)(ii) The areas are equal. By Kepler's second law, the line joining the spaceship to the planet sweeps out equal areas in equal times; the spaceship moves faster near O (A to B) and slower far away (C to D), so the thinner far segment has the same area as the wider near one.", [
    "(a) Identifies the gradient as GM/4π² (from Kepler's third law).",
    "(a) Calculates the gradient from the graph (≈ 3.2 × 10¹⁵ m³ s⁻²) with the axis scale factors.",
    "(a) M ≈ 1.9 × 10²⁷ kg.",
    "(b)(i) Uses v_esc = √(2GM/R) with R = 2R_E.",
    "(b)(i) v_esc ≈ 7.7 × 10⁴ m s⁻¹.",
    "(b)(ii) States the areas AOB and COD are equal.",
    "(b)(ii) Justifies with Kepler's second law (equal areas in equal times; faster when closer).",
  ]),
  s(7, "(a) r = 6.679 × 10⁶ / 2 = 3.34 × 10⁶ m. g = GM/r² = 6.67 × 10⁻¹¹ × 6.39 × 10²³ / (3.34 × 10⁶)² ≈ 3.82 m s⁻².\n(b)(i) u_y = 2.5 sin 25° = 1.06 m s⁻¹, so the rise above the launch point is u_y²/2g = 1.06² / (2 × 3.82) ≈ 0.15 m. Launched 2 m above the ground, the maximum distance from the centre is about 3.3395 × 10⁶ m + 2.15 m ≈ 3 339 502 m (essentially the radius of Mars).\n(b)(ii) Vertical: −2 = 1.06t − ½(3.82)t², giving t ≈ 1.34 s. Horizontal: u_x = 2.5 cos 25° = 2.27 m s⁻¹, so range = 2.27 × 1.34 ≈ 3.0 m.\n(c) v_esc = √(2GM/r) = √(2 × 6.67 × 10⁻¹¹ × 6.39 × 10²³ / 3.34 × 10⁶) ≈ 5.05 × 10³ m s⁻¹.", [
    "(a) Uses g = GM/r² with the radius (half the diameter).",
    "(a) g ≈ 3.82 m s⁻².",
    "(b)(i) Finds the maximum height above the launch point (≈ 0.15 m) using the vertical component.",
    "(b)(i) Adds the radius of Mars (and launch height) to give ≈ 3.3395 × 10⁶ m.",
    "(b)(ii) Resolves the velocity: u_x ≈ 2.27 m s⁻¹, u_y ≈ 1.06 m s⁻¹.",
    "(b)(ii) Sets up the vertical motion with a 2 m drop: −2 = u_y t − ½gt².",
    "(b)(ii) Solves for the time of flight, t ≈ 1.34 s.",
    "(b)(ii) Range ≈ 3.0 m.",
    "(c) Uses v_esc = √(2GM/r).",
    "(c) v_esc ≈ 5.05 × 10³ m s⁻¹.",
  ]),
  s(8, "Kepler's law of periods (T²/r³ = 4π²/GM) only compares objects orbiting the same central body, because the constant depends on the central mass. The HST does not orbit the Sun independently: it is in a small orbit around the Earth, held by Earth's gravity, so it travels around the Sun together with the Earth and must have the same period about the Sun. Its own orbit obeys Kepler's third law with Earth's mass as the central body, so there is no contradiction.", [
    "States that Kepler's third law applies to bodies orbiting the same central mass (the constant depends on that mass).",
    "Explains that the HST is gravitationally bound to the Earth (it orbits the Earth), so it moves around the Sun with the Earth.",
    "Concludes that its period around the Sun therefore equals Earth's, and its own orbit obeys Kepler's law for Earth, so there is no contradiction.",
  ]),
  s(9, "(a) In a circular orbit K = −U/2 and E = U/2.\nInitial: U = −4E, K = 2E, total = −2E.\nFinal: U = −E, K = 0.5E, total = −0.5E.\n(b) The potential energy has actually increased: −E is greater than −4E because it is less negative. Only its magnitude has decreased, because U = −GMm/r approaches zero as r increases; moving to a higher orbit requires work to be done on the rocket, raising U.\n(c) Gravity provides the centripetal force: GMm/r² = mv²/r, so mv² = GMm/r and K = ½mv² = GMm/2r. K is inversely proportional to r: the potential energy shows the radius increased by a factor of 4, so K falls from 2E to 0.5E.", [
    "(a) Initial row correct: U = −4E, K = 2E, total = −2E.",
    "(a) Final row correct: U = −E, K = 0.5E, total = −0.5E.",
    "(b) States that U has increased (−E > −4E; less negative).",
    "(b) Explains with U = −GMm/r: its magnitude decreases as r increases, with zero at infinity.",
    "(c) Derives K = GMm/2r from equating gravitational and centripetal force.",
    "(c) Uses K ∝ 1/r to justify the decrease from 2E to 0.5E (radius ×4).",
  ]),
  s(10, "Kepler's third law: r³/T² is the same for all the planets. Using Chinson: r_H = r_C (T_H/T_C)^(2/3) = 6.1 × 10⁸ × (8.4 × 10⁴ / 4.2 × 10⁴)^(2/3) = 6.1 × 10⁸ × 2^(2/3) ≈ 9.7 × 10⁸ m. (Using Danny gives ≈ 9.8 × 10⁸ m.)", [
    "Applies Kepler's third law (r³/T² constant) with data for another planet.",
    "r ≈ 9.7 × 10⁸ m (accept 9.7–9.8 × 10⁸ m).",
  ]),
  s(11, "Planet X turns through 120° (one third of an orbit) in 5 years, so T_X = 15 years. Kepler's third law: T_Y = T_X (r_Y/r_X)^(3/2) = 15 × (5/2)^(3/2) = 15 × 3.95 ≈ 59 years.", [
    "Finds T_X = 15 years (120° is one third of an orbit).",
    "Applies Kepler's third law: T_Y/T_X = (r_Y/r_X)^(3/2).",
    "T_Y ≈ 59 years.",
  ]),
  s(12, "(a) Kepler's third law: T² ∝ r³, so T ∝ r^(3/2). With r_R = 3r_S: T_R/T_S = 3^(3/2) = √27 ≈ 5.2, so T_R : T_S ≈ 5.2 : 1.\n(b) Gravity is the only force on an orbiting satellite and it provides the centripetal force: GMm/r² = mv²/r. This sets the orbital speed for each radius, v = √(GM/r), which depends only on the planet's mass and the radius, not on the satellite's mass, and gives a smaller speed for a larger orbit. Since v = 2πr/T, it also fixes the period: T² = 4π²r³/GM (Kepler's third law). In a circular orbit the force is perpendicular to the velocity, so it changes only the direction of motion and does no work: the speed and energy stay constant.", [
    "(a) States T² ∝ r³ (Kepler's third law).",
    "(a) Substitutes r_R = 3r_S: T_R/T_S = 3^(3/2).",
    "(a) T_R : T_S ≈ 5.2 : 1.",
    "(b) Gravity provides the centripetal force: GMm/r² = mv²/r.",
    "(b) Derives v = √(GM/r): speed depends on the planet's mass and the radius, not the satellite's mass.",
    "(b) Derives the period relationship T² = 4π²r³/GM.",
    "(b) Notes the force is perpendicular to the velocity (towards the centre), changing direction only, so speed is constant.",
  ]),
  s(13, "(a) T = 2π√(r³/GM) = 2π√((6.346 × 10⁶)³ / (6.67 × 10⁻¹¹ × 4.867 × 10²⁴)) ≈ 5.57 × 10³ s (about 93 minutes).\n(b) In orbit the total energy is E = −GMm/2r. To escape, the total energy must be raised to zero, so the extra work is W = GMm/2r = 6.67 × 10⁻¹¹ × 4.867 × 10²⁴ × 3445 / (2 × 6.346 × 10⁶) ≈ 8.8 × 10¹⁰ J.", [
    "(a) Uses T² = 4π²r³/GM (or equivalent).",
    "(a) T ≈ 5.57 × 10³ s.",
    "(b) Identifies the orbital total energy as E = −GMm/2r.",
    "(b) Recognises that the additional work must bring the total energy to zero (W = GMm/2r).",
    "(b) W ≈ 8.8 × 10¹⁰ J.",
  ]),
  s(14, "(a) Its velocity is constantly changing direction, so it is accelerating (centripetal acceleration towards the planet); a net force, gravity, must act towards the centre.\n(b) On Earth we feel our weight through the normal (reaction) force from the ground pushing up on us. In an orbiting satellite the person and the satellite are both in free fall, accelerating towards Earth at the same rate, so there is no normal force: they feel weightless even though gravity still acts.\n(c) The same speed. Gravity provides the centripetal force: GMm/r² = mv²/r, so v = √(GM/r); the satellite's mass cancels, so doubling its mass does not change the orbital speed in the same orbit.", [
    "(a) Direction of velocity changes, so there is a centripetal acceleration and a net (gravitational) force towards the centre.",
    "(b) Weight is felt as the normal/reaction force from a supporting surface.",
    "(b) In orbit the person and satellite are both in free fall with the same acceleration, so there is no normal force (apparent weightlessness).",
    "(c) States the orbital speed is the same.",
    "(c) Justifies with GMm/r² = mv²/r giving v = √(GM/r), independent of the satellite's mass.",
  ]),
  s(15, "T = 15.9 × 24 × 3600 = 1.374 × 10⁶ s; r = 1.22 × 10⁹ m.\n(a) M = 4π²r³/(GT²) = 4π² × (1.22 × 10⁹)³ / (6.67 × 10⁻¹¹ × (1.374 × 10⁶)²) ≈ 5.7 × 10²⁶ kg.\n(b) E = −GMm/2r = −6.67 × 10⁻¹¹ × 5.7 × 10²⁶ × 1.35 × 10²³ / (2 × 1.22 × 10⁹) ≈ −2.1 × 10³⁰ J.\n(c) Chemical energy in the fuel does work on the satellite, giving it kinetic energy. As it rises, its gravitational potential energy increases (becomes less negative), and it reaches orbit with the kinetic energy needed for a circular orbit (½mv² = GMm/2r); its total mechanical energy has increased from the surface value to −GMm/2r.", [
    "(a) Uses Kepler's third law with T in seconds and r in metres.",
    "(a) M ≈ 5.7 × 10²⁶ kg.",
    "(b) Uses E = −GMm/2r.",
    "(b) Substitutes Saturn's mass from (a), Titan's mass and r correctly.",
    "(b) E ≈ −2.1 × 10³⁰ J.",
    "(c) Work done by the rocket (from fuel) increases the satellite's gravitational potential energy.",
    "(c) Describes the kinetic energy changes: gained during launch, with the orbital kinetic energy ½mv² = GMm/2r in orbit (total energy increases).",
  ]),
  s(16, "From perihelion to aphelion the planet moves away from the Sun, so the speed decreases (it is fastest at perihelion and slowest at aphelion). The Sun's gravitational force has a component opposite to the planet's velocity, doing negative work: kinetic energy is converted into gravitational potential energy while total energy stays constant. This agrees with Kepler's second law: to sweep equal areas in equal times it must move more slowly when it is farther away.", [
    "States the speed decreases from perihelion to aphelion (fastest at perihelion, slowest at aphelion).",
    "Accounts for it with energy conservation (kinetic converted to gravitational potential energy as r increases) or Kepler's second law (equal areas in equal times).",
  ]),
  s(17, "r = 6.371 × 10⁶ + 2.0 × 10⁷ = 2.637 × 10⁷ m.\n(a) |U| = GMm/r = 6.67 × 10⁻¹¹ × 6.0 × 10²⁴ × 11 000 / 2.637 × 10⁷ ≈ 1.67 × 10¹¹ J.\n(b) GMm/r² = mv²/r, so v = √(GM/r) = √(6.67 × 10⁻¹¹ × 6.0 × 10²⁴ / 2.637 × 10⁷) ≈ 3.90 × 10³ m s⁻¹.", [
    "(a) Uses U = −GMm/r with r = R_E + altitude.",
    "(a) |U| ≈ 1.67 × 10¹¹ J.",
    "(b) Equates gravitational and centripetal force (or quotes v = √(GM/r)).",
    "(b) Substitutes the correct orbital radius.",
    "(b) v ≈ 3.9 × 10³ m s⁻¹.",
  ]),
  s(18, "A geostationary satellite stays above the same point on Earth, so: its period must equal Earth's rotation period (about 24 h, strictly 23 h 56 min); it must orbit above the equator; it must move in the same direction as Earth rotates (west to east); and its orbit must be circular, at constant speed. The period fixes the radius: r³ = GMT²/4π² = 6.67 × 10⁻¹¹ × 6.0 × 10²⁴ × (86 400)² / 4π², giving r ≈ 4.2 × 10⁷ m, an altitude of about 3.6 × 10⁷ m (36 000 km), with orbital speed v = 2πr/T ≈ 3.1 × 10³ m s⁻¹.", [
    "Period equal to Earth's rotation period (about 24 hours).",
    "Orbit in the equatorial plane, moving in the same direction as Earth's rotation.",
    "Uses Kepler's third law to calculate the orbital radius.",
    "r ≈ 4.2 × 10⁷ m (altitude ≈ 3.6 × 10⁷ m).",
  ]),
  s(19, "(a) Gravity provides the centripetal force: GMm/(R + h)² = mω²(R + h), so ω² = GM/(R + h)³ and ω = √(GM/(R + h)³). (Or: from Kepler's third law T² = 4π²(R + h)³/GM and ω = 2π/T.)\n(b) r = 6.371 × 10⁶ + 2.02 × 10⁷ = 2.657 × 10⁷ m. T = 2π√(r³/GM) = 2π√((2.657 × 10⁷)³ / (6.67 × 10⁻¹¹ × 6.0 × 10²⁴)) ≈ 4.30 × 10⁴ s (about 12 hours).\n(c) U = −GMm/r = −6.67 × 10⁻¹¹ × 6.0 × 10²⁴ × 1630 / 2.657 × 10⁷ ≈ −2.46 × 10¹⁰ J.\n(d) The linear speed is v = √(GM/r), so the satellite in the higher orbit (larger r) has a lower linear speed. The gravitational force (and the centripetal force it provides) is weaker farther out, so a smaller speed keeps it in a circular orbit.", [
    "(a) Equates gravitational force with centripetal force (or uses Kepler's third law) with radius R + h.",
    "(a) Rearranges correctly to ω = √(GM/(R + h)³) using ω = 2π/T.",
    "(b) Uses the orbital radius R + h = 2.657 × 10⁷ m.",
    "(b) T ≈ 4.30 × 10⁴ s.",
    "(c) Uses U = −GMm/r.",
    "(c) U ≈ −2.46 × 10¹⁰ J.",
    "(d) States the higher satellite has a lower linear speed.",
    "(d) Explains using v = √(GM/r) (weaker gravitational force at larger r).",
  ]),
  s(20, "Low Earth orbits are within the thin upper atmosphere, so the satellites experience atmospheric drag (friction). Drag does negative work, removing energy, so the satellite drops to a lower orbit, where the air is denser and drag is greater. The orbit decays faster and faster until the satellite re-enters the atmosphere and falls to the surface (unless it is boosted).", [
    "Identifies atmospheric drag (friction with the upper atmosphere) acting on satellites in low Earth orbit.",
    "Explains that the drag removes energy so the orbit decays (lower orbit, more drag) until it re-enters.",
  ]),
  s(21, "(a) Mass is the same everywhere: W = mg = 600 × 9.8 ≈ 5.9 × 10³ N.\n(b) Kepler's third law: M = 4π²r³/(GT²) = 4π² × (3.0 × 10⁴)³ / (6.67 × 10⁻¹¹ × (7.9 × 10⁴)²) ≈ 2.6 × 10¹⁵ kg.", [
    "(a) W = mg = 600 × 9.8 ≈ 5.9 × 10³ N (the mass is unchanged).",
    "(b) Uses r³/T² = GM/4π² with r in metres (3.0 × 10⁴ m).",
    "(b) M ≈ 2.6 × 10¹⁵ kg.",
  ]),
  s(22, "r = 6.371 × 10⁶ + 2.7129 × 10⁷ = 3.35 × 10⁷ m. U = −GMm/r = −6.67 × 10⁻¹¹ × 6.0 × 10²⁴ × 250 / 3.35 × 10⁷ ≈ −3.0 × 10⁹ J. Escape velocity is the minimum speed an object needs, at that point, to escape the gravitational field completely (reach infinite distance) without further propulsion, i.e. so that K + U = 0. v_esc = √(2GM/r) = √(2 × 6.67 × 10⁻¹¹ × 6.0 × 10²⁴ / 3.35 × 10⁷) ≈ 4.9 × 10³ m s⁻¹.", [
    "Uses the orbital radius r = R_E + altitude = 3.35 × 10⁷ m.",
    "U ≈ −3.0 × 10⁹ J.",
    "v_esc = √(2GM/r) ≈ 4.9 × 10³ m s⁻¹.",
    "Explains escape velocity: the minimum initial speed for an object to escape the gravitational field without further propulsion (total energy zero).",
  ]),
  s(23, "A geostationary satellite orbits above the equator, in the direction of Earth's rotation, with a period of 24 hours (equal to Earth's rotation period), at an altitude of about 36 000 km, so it stays above the same point on Earth. One important function: telecommunications (TV and phone relay), or weather observation.", [
    "Period equal to Earth's rotation period (24 h), so it stays above the same point on the surface.",
    "Orbits above the equator in the direction of Earth's rotation (altitude ≈ 36 000 km).",
    "One function, e.g. communications, weather observation.",
  ]),
  s(24, "(a) g = GM/r² = 6.67 × 10⁻¹¹ × 7.342 × 10²² / (1.7374 × 10⁶)² ≈ 1.62 m s⁻².\n(b) On level ground the range is R = u² sin 2θ / g, so u = √(Rg / sin 70°) = √(40.0 × 1.62 / 0.940) ≈ 8.31 m s⁻¹.\n(c) h = (u sin θ)² / 2g = (8.31 × sin 35°)² / (2 × 1.62) ≈ 7.0 m.", [
    "(a) Uses g = GM/r² with r in metres.",
    "(a) g ≈ 1.62 m s⁻².",
    "(b) Uses the range equation (or time of flight and horizontal motion).",
    "(b) Substitutes R = 40.0 m, θ = 35.0° and the Moon's g.",
    "(b) u ≈ 8.3 m s⁻¹.",
    "(c) Uses v_y² = u_y² − 2gh with u_y = u sin 35°.",
    "(c) h ≈ 7.0 m.",
  ]),
  s(25, "(a) Mercury: its aphelion (69.8) and perihelion (46) differ the most relative to its average distance.\n(b) At perihelion, 206.6 × 10⁶ km from the Sun. Kepler's second law (equal areas in equal times): the planet moves fastest when closest to the Sun.\n(c) F = GMm/r² = 6.67 × 10⁻¹¹ × 2.00 × 10³⁰ × 0.33 × 10²⁴ / (57.9 × 10⁹)² ≈ 1.3 × 10²² N.", [
    "(a) Mercury.",
    "(b) At perihelion, 206.6 × 10⁶ km.",
    "(b) Kepler's second law (equal areas in equal times).",
    "(c) Uses F = GMm/r² with the average distance converted to metres (5.79 × 10¹⁰ m).",
    "(c) Correct substitution of both masses.",
    "(c) F ≈ 1.3 × 10²² N.",
  ]),
  s(26, "In a stable circular orbit the gravitational force exactly provides the centripetal force needed at that speed, mv²/r = GMm/r². Firing the rockets to increase the speed makes the required centripetal force greater than gravity can provide, so the satellite moves outward into an elliptical path. As it rises, kinetic energy is converted into gravitational potential energy and it slows down. When it reaches the higher orbit its speed is not right for a circular orbit at that radius, so the rockets are fired again to adjust the speed to v = √(GM/r) for the new radius. The new circular orbit has a lower speed than the original (v = √(GM/r) decreases with r), but more total energy (E = −GMm/2r is less negative); the work done by the rockets supplies this energy.", [
    "In a stable orbit gravity provides exactly the centripetal force for that speed (v = √(GM/r)).",
    "Increasing the speed means gravity is less than the required centripetal force, so the satellite moves outward (elliptical transfer path), converting kinetic to potential energy.",
    "At the new radius the speed must be adjusted to match v = √(GM/r) for a stable circular orbit there.",
    "Higher orbits have lower orbital speed but greater total energy; the rockets do the work to supply it.",
  ]),
  s(27, "Gravity is the only significant force on a planet or satellite and it acts towards the centre of the central body, providing the centripetal force: GMm/r² = mv²/r. This sets the orbital speed for each radius, v = √(GM/r), independent of the orbiting body's mass (smaller speed for larger orbits), and the period, T² = 4π²r³/GM (Kepler's third law). Being perpendicular to the velocity in a circular orbit, gravity changes only the direction of motion, so the speed is constant. In an elliptical orbit it has a component along the velocity, so the body speeds up as it approaches the central body and slows as it moves away (Kepler's second law), with total energy conserved.", [
    "Gravity provides the centripetal force: GMm/r² = mv²/r.",
    "Derives v = √(GM/r): speed depends on the central mass and radius, not the orbiting mass.",
    "Links to Kepler's third law: T² = 4π²r³/GM.",
    "Explains the direction of the force: perpendicular to velocity in circular orbits (constant speed) or speeding up and slowing down in elliptical orbits.",
  ]),
  s(28, "(a) g_J = GM_J/r² = 6.67 × 10⁻¹¹ × 1.9 × 10²⁷ / (4.2 × 10¹¹)² ≈ 7.2 × 10⁻⁷ N kg⁻¹ towards Jupiter. g_S = 6.67 × 10⁻¹¹ × 5.7 × 10²⁶ / (3.9 × 10¹¹)² ≈ 2.5 × 10⁻⁷ N kg⁻¹ towards Saturn. They are in opposite directions, so the total is 7.2 × 10⁻⁷ − 2.5 × 10⁻⁷ ≈ 4.7 × 10⁻⁷ N kg⁻¹.\n(b) Towards Jupiter (along the line from Cassini to Jupiter).\n(c) T = 10.7 h = 10.7 × 3600 ≈ 3.85 × 10⁴ s.", [
    "(a) Calculates both field strengths (≈ 7.2 × 10⁻⁷ and 2.5 × 10⁻⁷ N kg⁻¹).",
    "(a) Subtracts them because they are opposite: ≈ 4.7 × 10⁻⁷ N kg⁻¹.",
    "(b) Direction towards Jupiter.",
    "(c) T ≈ 3.85 × 10⁴ s.",
  ]),
  s(29, "(a) a = Δv/t = 7.5 / 2.0 = 3.75 m s⁻² (≈ 3.8 m s⁻²).\n(b) g = GM/r², so M = gr²/G = 3.75 × (3.4 × 10⁶)² / 6.67 × 10⁻¹¹ ≈ 6.5 × 10²³ kg.", [
    "(a) Uses a = Δv/t.",
    "(a) g ≈ 3.75 m s⁻².",
    "(b) Uses g = GM/r².",
    "(b) Rearranges to M = gr²/G and substitutes.",
    "(b) M ≈ 6.5 × 10²³ kg.",
  ]),
  s(30, "(a) Geostationary orbit: period of 24 hours (same as Earth's rotation), above the equator moving in the same direction as Earth rotates, at an altitude of about 36 000 km, so the satellite stays above the same point. Advantage: ground antennas can point at a fixed position with no tracking, giving uninterrupted communication over a large area.\n(b) In orbit E = K + U = −GMm/2r (since K = −U/2). r = 6.371 × 10⁶ + 4.0 × 10⁵ = 6.771 × 10⁶ m. E = −6.67 × 10⁻¹¹ × 6.0 × 10²⁴ × 750 / (2 × 6.771 × 10⁶) ≈ −2.2 × 10¹⁰ J.", [
    "(a) Describes features: 24 h period matching Earth's rotation, above the equator (fixed position above the surface).",
    "(a) Advantage for communications: fixed antennas / continuous coverage of the same region.",
    "(b) Uses E = −GMm/2r (or U + K).",
    "(b) Uses r = R_E + 400 km = 6.771 × 10⁶ m.",
    "(b) E ≈ −2.2 × 10¹⁰ J.",
  ]),
  s(31, "(a) T = 7.0 days / 11.2 = 0.625 days = 5.4 × 10⁴ s.\n(b)(i) A synchronous orbit has T = 7.0 days, 11.2 times the low-orbit period. r ∝ T^(2/3), so r = 3.46 × 10⁷ × 11.2^(2/3) ≈ 1.73 × 10⁸ m.\n(ii) It must orbit above the planet's equator, in the same direction as the planet rotates.\n(iii) M = 4π²r³/(GT²) = 4π² × (3.46 × 10⁷)³ / (6.67 × 10⁻¹¹ × (5.4 × 10⁴)²) ≈ 8.4 × 10²⁴ kg.", [
    "(a) T = 0.625 days = 5.4 × 10⁴ s.",
    "(b)(i) Uses Kepler's third law with the synchronous period of 7.0 days.",
    "(b)(i) r ≈ 1.7 × 10⁸ m.",
    "(b)(ii) Orbit above the equator, in the direction of the planet's rotation.",
    "(b)(iii) Uses r³/T² = GM/4π² with consistent data (SI units).",
    "(b)(iii) Correct substitution.",
    "(b)(iii) M ≈ 8.4 × 10²⁴ kg.",
  ]),
  s(32, "(a) Kepler's third law for Earth: R³ = GM_S T²/4π² = 6.67 × 10⁻¹¹ × 2.0 × 10³⁰ × (3.16 × 10⁷)² / 4π², so R ≈ 1.5 × 10¹¹ m.\n(b) Two forces act on DSCOVR: the Sun's gravitational force towards the Sun, and the Earth's gravitational force towards the Earth (away from the Sun). Their resultant provides the centripetal force for a circular orbit of radius R − d with period T_E:\nGM_S m/(R − d)² − GM_E m/d² = m · 4π²(R − d)/T_E².", [
    "(a) Uses Kepler's third law with the Sun's mass and Earth's period.",
    "(a) R ≈ 1.5 × 10¹¹ m.",
    "(b) Identifies both forces: the Sun's gravity (towards the Sun) and Earth's gravity (towards Earth, away from the Sun).",
    "(b) States that the net force provides the centripetal force for an orbit of radius R − d with period T_E.",
    "(b) Writes a correct equation, e.g. GM_S m/(R − d)² − GM_E m/d² = 4π²m(R − d)/T_E².",
  ]),
  s(33, "Orbital velocity: v = √(GM/r), so low Earth orbits (about 200–2000 km altitude) are fast, about 7–8 km s⁻¹, while geostationary orbits (altitude ≈ 36 000 km) are slower, about 3 km s⁻¹. Orbital period: low orbits take about 90–120 minutes, whereas a geostationary orbit takes 24 hours, matching Earth's rotation so the satellite stays above one point. Uses: low orbits suit detailed imaging, mapping, reconnaissance, some weather and the ISS, because they are close and pass over different regions; geostationary orbits suit communications, TV broadcasting and weather monitoring of a fixed region, because fixed ground antennas can point at them continuously.", [
    "Compares orbital velocity: LEO faster (≈ 7–8 km s⁻¹) than GEO (≈ 3 km s⁻¹), linked to v = √(GM/r).",
    "Compares period: LEO ≈ 90 min; GEO 24 h (matches Earth's rotation).",
    "Gives uses of LEO linked to their features (close, cover different areas: imaging, mapping, ISS).",
    "Gives uses of GEO linked to their features (fixed position: communications, weather over one region).",
  ]),
  s(34, "(a) Any two: period equal to Earth's rotation period (24 h); orbit above the equator; travels in the same direction as Earth's rotation; altitude about 36 000 km (radius ≈ 4.2 × 10⁷ m); stays above the same point on the surface.\n(b) The speed increases. Gravity provides the centripetal force, GMm/r² = mv²/r, so v = √(GM/r): a smaller orbital radius requires a greater orbital speed.", [
    "(a) First correct feature.",
    "(a) Second correct feature.",
    "(b) States the speed increases in a lower orbit.",
    "(b) Justifies using v = √(GM/r) (from gravity providing the centripetal force).",
  ]),
  s(35, "The smallest possible orbit has a radius just above Earth's surface (in practice above the atmosphere, otherwise drag would bring it down). Kepler's third law: T = 2π√(r³/GM). With r = R_E = 6.371 × 10⁶ m, T = 2π√((6.371 × 10⁶)³ / (6.67 × 10⁻¹¹ × 6.0 × 10²⁴)) ≈ 5.05 × 10³ s ≈ 84 minutes. Since T increases with r, and a real orbit must be above the atmosphere (≥ about 100–200 km, giving ≈ 86–88 min), no Earth satellite can have a period less than about 85 minutes.", [
    "Identifies that the minimum orbital radius is about Earth's radius (above the atmosphere).",
    "Calculates T = 2π√(r³/GM) ≈ 84 min (5.1 × 10³ s) for r ≈ R_E.",
    "Explains that the period increases with radius, so no orbit can have a shorter period.",
  ]),
  s(36, "(a) At the Moon's surface (r ≈ 1.74 × 10⁶ m) the graph gives F ≈ 1.62 × 10³ N. F = GMm/r², so M = Fr²/(Gm) = 1.62 × 10³ × (1.74 × 10⁶)² / (6.67 × 10⁻¹¹ × 1000) ≈ 7.4 × 10²² kg. (Any point on the curve can be used.)\n(b) v_esc = √(2GM/r) = √(2 × 6.67 × 10⁻¹¹ × 7.4 × 10²² / 1.74 × 10⁶) ≈ 2.4 × 10³ m s⁻¹.", [
    "(a) Reads a pair of values from the graph and uses F = GMm/r².",
    "(a) M ≈ 7.3–7.4 × 10²² kg.",
    "(b) Uses v_esc = √(2GM/r) at the Moon's surface.",
    "(b) v ≈ 2.4 × 10³ m s⁻¹.",
  ]),
  s(37, "r = 6.371 × 10⁶ + 5.0 × 10⁵ = 6.871 × 10⁶ m.\n(a) v = √(GM/r) = √(6.67 × 10⁻¹¹ × 6.0 × 10²⁴ / 6.871 × 10⁶) ≈ 7.6 × 10³ m s⁻¹.\n(b) |U| = GMm/r = 6.67 × 10⁻¹¹ × 6.0 × 10²⁴ × 250 / 6.871 × 10⁶ ≈ 1.5 × 10¹⁰ J.\n(c) v_esc = √(2GM/r) = √2 × 7.63 × 10³ ≈ 1.1 × 10⁴ m s⁻¹.\n(d) A higher orbit has greater (less negative) total energy, E = −GMm/2r. The gravitational potential energy increases more than the kinetic energy decreases, so energy must be supplied: the engines must do work against gravity to raise the satellite and then adjust its speed for the new orbit.", [
    "(a) Uses v = √(GM/r) with r = R_E + altitude.",
    "(a) v ≈ 7.6 × 10³ m s⁻¹.",
    "(b) Uses U = −GMm/r.",
    "(b) |U| ≈ 1.5 × 10¹⁰ J.",
    "(c) Uses v_esc = √(2GM/r) at the orbital radius.",
    "(c) v_esc ≈ 1.1 × 10⁴ m s⁻¹.",
    "(d) A higher orbit has greater total energy (E = −GMm/2r is less negative).",
    "(d) The engines must supply this energy by doing work against gravity (increase in U is greater than the decrease in K).",
  ]),
  s(38, "(a) The gravitational force provides the centripetal force: GMm/r² = mv²/r. Cancelling m and one r: v² = GM/r, so v = √(GM/r).\n(b) r = 6.37 × 10⁶ + 1.0 × 10⁶ = 7.37 × 10⁶ m. v = √(6.67 × 10⁻¹¹ × 6.0 × 10²⁴ / 7.37 × 10⁶) ≈ 7.4 × 10³ m s⁻¹.", [
    "(a) Equates GMm/r² with mv²/r.",
    "(a) Simplifies to v = √(GM/r).",
    "(b) Uses r = 6370 km + 1000 km = 7.37 × 10⁶ m.",
    "(b) v ≈ 7.4 × 10³ m s⁻¹.",
  ]),
  s(39, "Satellite A is in a low Earth orbit: imaging the weather over different continents needs a satellite close to Earth (a few hundred km), giving detailed images, and with a short period (about 90 minutes) so it passes over different regions as the Earth rotates beneath it. Satellite B is geostationary: a communications satellite should stay above the same point on Earth so fixed antennas can stay pointed at it, which requires a 24-hour period above the equator at an altitude of about 36 000 km.", [
    "Satellite A is a LEO.",
    "Justifies A: low altitude for detailed images and a short period, so it moves over different regions.",
    "Satellite B is a GEO, justified by its 24 h period above the equator keeping it at a fixed position for communications.",
  ]),
  s(40, "All four moons orbit the same central body (Saturn), so by Kepler's third law r³/T² = GM/4π² is the same constant for every moon. Calculate r³/T² from the table data (or the gradient of a graph of r³ against T²); this constant (≈ 9.6 × 10¹⁴ m³ s⁻² for these moons) also applies to Rhea. Rearranging r³ = constant × T² with Rhea's period of 3.90 × 10⁵ s gives its orbital radius (≈ 5.3 × 10⁸ m).", [
    "States Kepler's third law: r³/T² is constant for bodies orbiting the same central mass.",
    "Describes finding the constant from the data (average of r³/T² or the gradient of r³ vs T²).",
    "Describes using the constant with Rhea's period to find its radius: r = (constant × T²)^(1/3).",
  ]),
  s(41, "(a) U = −GMm/r = −6.67 × 10⁻¹¹ × 6.39 × 10²³ × 677 / 3.805 × 10⁶ ≈ −7.6 × 10⁹ J.\n(b) Total mechanical energy (K + U) is conserved because gravity is the only force acting. A is the closest point, where r is smallest and U = −GMm/r is lowest (most negative), so K = E − U, and therefore the speed, is greatest at A. This agrees with Kepler's second law: the line from Mars to the satellite sweeps equal areas in equal times, so the satellite must move fastest where it is closest.", [
    "(a) Uses U = −GMm/r with r = 3.805 × 10⁶ m.",
    "(a) Correct substitution giving ≈ −7.6 × 10⁹ J.",
    "(b) Total mechanical energy is conserved (gravity is the only force).",
    "(b) At A the potential energy is lowest (most negative) because r is smallest, so kinetic energy and speed are greatest.",
    "(b) Links to Kepler's second law (equal areas in equal times: fastest when closest).",
  ]),
  s(42, "(a) Gravity provides the centripetal force: GMm/r² = 4π²mr/T², so r³/T² = GM/4π². For satellites of the same planet GM/4π² is constant, so r³ ∝ T²: a straight line through the origin (Kepler's third law).\n(b) Gradient = r³/T² = 16 × 10²² / 2.5 × 10⁹ = 6.4 × 10¹³ m³ s⁻². For r = 5.2 × 10⁷ m, r³ = 1.41 × 10²³ m³, so T² = 1.41 × 10²³ / 6.4 × 10¹³ = 2.2 × 10⁹ s² and T ≈ 4.7 × 10⁴ s.", [
    "(a) Equates gravitational and centripetal force to derive r³/T² = GM/4π².",
    "(a) States that GM/4π² is constant for one planet, so r³ ∝ T² (straight line through the origin).",
    "(b) Finds the gradient from the graph: ≈ 6.4 × 10¹³ m³ s⁻² (with the axis scale factors).",
    "(b) Uses T² = r³ / gradient with r³ = 1.41 × 10²³ m³.",
    "(b) T ≈ 4.7 × 10⁴ s.",
  ]),
  s(43, "(a) Projectile a (it falls to Earth closest to the mountain).\n(b) Escape velocity is the minimum speed an object must be given at a point (for example the surface) so that, with no further propulsion, it escapes the gravitational field completely, reaching an infinite distance; at that speed its kinetic energy equals the magnitude of its gravitational potential energy (total energy zero).\n(c) r = 6.371 × 10⁶ + 3.0 × 10⁵ = 6.671 × 10⁶ m. T = 2π√(r³/GM) = 2π√((6.671 × 10⁶)³ / (6.67 × 10⁻¹¹ × 6.0 × 10²⁴)) ≈ 5.4 × 10³ s (about 90 minutes).", [
    "(a) Projectile a.",
    "(b) Minimum launch speed needed to escape the gravitational field (reach infinite distance)…",
    "(b) …without further propulsion (kinetic energy equals the magnitude of the potential energy; total energy zero).",
    "(c) Uses the orbital radius r = 6371 km + 300 km.",
    "(c) Uses T² = 4π²r³/GM.",
    "(c) T ≈ 5.4 × 10³ s.",
  ]),
  s(44, "(a) From the graph, Ep ≈ −3.9 × 10⁹ J at 9000 km and ≈ −6.4 × 10⁹ J at 3000 km, so ΔEp ≈ −2.5 × 10⁹ J (a decrease of about 2.5 × 10⁹ J).\n(b) Gravitational potential energy is defined as zero at an infinite distance, where the gravitational force is zero. Gravity is attractive, so work must be done on a mass to move it out to infinity; the mass therefore has less energy than at infinity at every closer point, so its potential energy is negative (U = −GMm/r).", [
    "(a) ΔEp ≈ −2.5 × 10⁹ J (a decrease).",
    "(b) Zero of potential energy is defined at infinity.",
    "(b) Gravity is attractive, so work must be done to move the mass to infinity; it has less energy at any finite distance, so U is negative.",
  ]),
  s(45, "(a) By Kepler's second law, the line from the Sun to the planet sweeps out equal areas in equal times. The shaded areas are equal, so the planet takes the same time to go from A to B as from C to D. The arc A to B (close to the Sun) is much longer than the arc C to D, so the planet covers a greater distance in the same time: it travels faster between A and B.\n(b) A geostationary orbit is circular, so the satellite's distance from Earth, and hence its gravitational potential energy, is constant. Its speed is constant, so its kinetic energy is constant. Gravity, the only force, is always perpendicular to its velocity and does no work, so the total energy does not change.", [
    "(a) States Kepler's second law: equal areas swept in equal times.",
    "(a) Equal shaded areas mean equal times for A–B and C–D.",
    "(a) A–B is the longer arc, so the planet is faster between A and B.",
    "(b) Circular orbit: constant radius and speed, so U and K are both constant.",
    "(b) Gravity is perpendicular to the velocity and does no work (no other forces), so total energy is constant.",
  ]),
  s(46, "(a) With no propulsion, K + U is constant. As the height increases U rises (becomes less negative), so K decreases by the same amount: the kinetic energy line starts at its maximum (positive) value at the surface and curves down as height increases, as a mirror image (reflection) of the potential energy curve, until it reaches zero at the maximum height (or levels off above zero if the object escapes).\n(b) To just escape, the object must reach infinity with zero speed, where U = 0, so its total energy is zero: ½mv² − GMm/r = 0. Rearranging: v² = 2GM/r, so v = √(2GM/r). For Earth: v = √(2 × 6.67 × 10⁻¹¹ × 6.0 × 10²⁴ / 6.371 × 10⁶) ≈ 1.12 × 10⁴ m s⁻¹ = 11.2 km s⁻¹.", [
    "(a) Kinetic energy is greatest at the surface and decreases as height increases.",
    "(a) The decrease matches the rise in potential energy (mirror image of the U curve, since K + U is constant).",
    "(b) States the escape condition: total energy zero (½mv² = GMm/r).",
    "(b) Rearranges to v = √(2GM/r).",
    "(b) Substitutes Earth's mass and radius.",
    "(b) Obtains 1.12 × 10⁴ m s⁻¹ (11.2 km s⁻¹).",
  ]),
  s(47, "(a) In a circular orbit K = −E and U = 2E. The kinetic energy line is the mirror image of the total energy curve above the axis (positive, the same size as E at every radius). The gravitational potential energy line is below the total energy curve, twice as negative at every radius; all three approach zero as the radius increases.\n(b) r₁ = 6.371 × 10⁶ + 1.0 × 10⁵ = 6.471 × 10⁶ m; r₂ = 6.571 × 10⁶ m. ΔU = GMm(1/r₁ − 1/r₂) = 6.67 × 10⁻¹¹ × 6.0 × 10²⁴ × 300 × (1/6.471 × 10⁶ − 1/6.571 × 10⁶) ≈ +2.8 × 10⁸ J.", [
    "(a) Kinetic energy: positive, equal in magnitude to the total energy (K = −E).",
    "(a) Potential energy: negative, twice the total energy (U = 2E).",
    "(b) Uses U = −GMm/r with r = R_E + altitude for both orbits.",
    "(b) Correct substitution of both radii.",
    "(b) ΔU ≈ +2.8 × 10⁸ J (an increase).",
  ]),
  s(48, "r = 6.371 × 10⁶ + 4.00 × 10⁵ = 6.771 × 10⁶ m.\n(a) v = √(GM/r) = √(6.67 × 10⁻¹¹ × 6.0 × 10²⁴ / 6.771 × 10⁶) ≈ 7.69 × 10³ m s⁻¹.\n(b) U = −GMm/r = −6.67 × 10⁻¹¹ × 6.0 × 10²⁴ × 4.2 × 10⁵ / 6.771 × 10⁶ ≈ −2.5 × 10¹³ J.\n(c) E = U/2 = −GMm/2r ≈ −1.2 × 10¹³ J.\n(d) Zero: gravity acts towards the centre, perpendicular to the velocity throughout a circular orbit, so no work is done (and it returns to the same point with the same energy).", [
    "(a) Uses v = √(GM/r) with r = R_E + 400 km.",
    "(a) v ≈ 7.7 × 10³ m s⁻¹.",
    "(b) Uses U = −GMm/r.",
    "(b) U ≈ −2.5 × 10¹³ J.",
    "(c) Uses E = K + U = −GMm/2r (= U/2).",
    "(c) E ≈ −1.2 × 10¹³ J.",
    "(d) Zero work, because the gravitational force is perpendicular to the displacement (velocity) at all times.",
  ]),
  s(49, "(a) ω = 2π/T = 2π / (4 × 3600) = 4.36 × 10⁻⁴ rad s⁻¹. At the equator part of the gravitational force provides the centripetal force: N = mg − mω²R. a_c = ω²R = (4.36 × 10⁻⁴)² × 6.371 × 10⁶ ≈ 1.21 m s⁻². Apparent weight N = 60.0 × (9.8 − 1.21) ≈ 5.2 × 10² N (compared with 588 N with no rotation).\n(b) Any two, e.g.: Altitude: g = GM/r² decreases with height above the surface, so g is smaller on mountains. Latitude (shape of the Earth): Earth bulges at the equator, so the surface is farther from the centre there and g is smaller than at the poles. Local density / geology: dense rock or ore deposits beneath the surface increase g slightly.", [
    "(a) Calculates ω = 2π/T (or v = 2πR/T) for a 4-hour period.",
    "(a) Calculates the centripetal acceleration ω²R ≈ 1.2 m s⁻² (force ≈ 73 N).",
    "(a) Apparent weight = mg − mω²R ≈ 5.2 × 10² N.",
    "(b) First factor with its effect (e.g. altitude: g decreases with height).",
    "(b) Second factor with its effect (e.g. latitude/Earth's shape or local density of the crust).",
  ]),
  s(50, "(a) The gravitational force (Earth's gravity), directed from the satellite towards the centre of the Earth.\n(b) r = 12 560/2 + 20 000 = 26 280 km = 2.628 × 10⁷ m. a = GM/r² = 6.67 × 10⁻¹¹ × 6.0 × 10²⁴ / (2.628 × 10⁷)² ≈ 0.58 m s⁻² (towards Earth's centre).", [
    "(a) Gravitational force, directed towards the centre of the Earth.",
    "(b) Uses r = radius of Earth (half the diameter) + altitude = 2.628 × 10⁷ m with a = GM/r².",
    "(b) a ≈ 0.58 m s⁻².",
  ]),
  s(51, "(a) U = −GMm/r = −6.67 × 10⁻¹¹ × 6.0 × 10²⁴ × 250 / 3.35 × 10⁷ ≈ −3.0 × 10⁹ J.\n(b)(i) Kinetic energy decreases (K = GMm/2r).\n(ii) Gravitational potential energy increases (becomes less negative).\n(iii) Total mechanical energy increases (E = −GMm/2r becomes less negative).", [
    "(a) Uses U = −GMm/r with r = 3.35 × 10⁷ m.",
    "(a) U ≈ −3.0 × 10⁹ J.",
    "(b)(i) Kinetic energy decreases.",
    "(b)(ii) Gravitational potential energy increases.",
    "(b)(iii) Total mechanical energy increases.",
  ]),
  s(52, "Newton's law of universal gravitation, F = GMm/r², describes the attractive force between Earth and a satellite. It is the only significant force on an orbiting satellite and provides the centripetal force: GMm/r² = mv²/r. This lets us calculate the orbital speed for any radius, v = √(GM/r), and shows that it does not depend on the satellite's mass. It also gives the gravitational field g = GM/r², the potential energy U = −GMm/r, the total energy −GMm/2r and the escape velocity √(2GM/r), used to plan launches and orbit changes. Kepler's third law, r³/T² = constant, was originally empirical; Newton's law explains it: combining F = GMm/r² with v = 2πr/T gives r³/T² = GM/4π². This allows the period of a satellite to be calculated for a chosen radius (for example r ≈ 4.2 × 10⁷ m for a 24-hour geostationary orbit, or about 90 minutes for a low Earth orbit), compares satellites with each other, and allows Earth's mass to be found from a satellite's orbit. Together the two laws underpin the design of LEO and GEO orbits and make satellite motion predictable, though they assume circular orbits and ignore drag and the effects of other bodies.", [
    "States Newton's law of universal gravitation, F = GMm/r², and that gravity provides the centripetal force for a satellite.",
    "Derives or uses v = √(GM/r) to calculate orbital speed (independent of satellite mass).",
    "Uses Newton's law for related quantities (g, U = −GMm/r, total energy or escape velocity).",
    "States Kepler's third law (r³/T² constant for bodies orbiting the same mass).",
    "Shows Kepler's third law follows from Newton's law: r³/T² = GM/4π².",
    "Applies the laws to calculations, e.g. the radius of a geostationary orbit or the period of a LEO satellite, or finding Earth's mass.",
    "Discusses the importance and limits, e.g. predicting and designing orbits; assumes circular orbits and no drag.",
  ]),
  s(53, "(a) The only force on each star is their mutual gravitational attraction, which provides each star's centripetal force. By Newton's third law the force of Star 1 on Star 2 equals the force of Star 2 on Star 1 in magnitude, so the centripetal forces are equal.\n(b) Equal centripetal forces with equal ω: M₁ω²r₁ = M₂ω²r₂, so M₁r₁ = M₂r₂. With M₁ = 3M₂: r₂ = 3r₁, and r₁ + r₂ = d = 2.8 × 10¹¹ m, so r₁ = d/4 = 7.0 × 10¹⁰ m (7.0 × 10⁷ km).\n(c) For Star 2: GM₁M₂/d² = M₂ω²r₂, so M₁ = ω²r₂d²/G = (4.98 × 10⁻⁸)² × 2.1 × 10¹¹ × (2.8 × 10¹¹)² / 6.67 × 10⁻¹¹ ≈ 6.1 × 10²⁹ kg. Then M₂ = M₁/3 ≈ 2.0 × 10²⁹ kg.", [
    "(a) The centripetal force on each star is provided by their mutual gravitational attraction.",
    "(a) By Newton's third law these forces are equal in magnitude, so the centripetal forces are the same.",
    "(b) Equates centripetal forces with the same ω: M₁r₁ = M₂r₂.",
    "(b) Uses M₁ = 3M₂ and r₁ + r₂ = 2.8 × 10¹¹ m (converted to metres).",
    "(b) r₁ = 7.0 × 10¹⁰ m.",
    "(c) Sets the gravitational force (separation d) equal to the centripetal force on one star.",
    "(c) M₂ ≈ 2.0 × 10²⁹ kg.",
  ]),
  s(54, "Similarity: both undergo uniform circular motion; the force (gravitational on the satellite, magnetic on the particle) is perpendicular to the velocity and towards the centre, providing the centripetal force, so the speed is constant and no work is done. Difference: the satellite's centripetal force comes from gravity acting on its mass (GMm/r², orbital speed v = √(GM/r), independent of the satellite's mass), whereas the particle's comes from the magnetic force on a moving charge (qvB), with radius r = mv/qB, which depends on its mass, charge and speed (a faster particle moves in a larger circle, but a satellite in a larger orbit is slower).", [
    "Similarity: both move in uniform circular motion with a centripetal force perpendicular to the velocity (constant speed, no work done).",
    "Difference: identifies the different sources of the force (gravity on mass vs magnetic force qvB on a moving charge).",
    "Explains the consequence of the difference, e.g. r = mv/qB (larger r for faster particles) vs v = √(GM/r) (slower for larger orbits, independent of mass).",
  ]),
  s(55, "(a) W = mg = 0.500 × 9.8 = 4.9 N (downward).\n(b) At infinity both the kinetic energy (just escaping, zero speed) and the gravitational potential energy are zero, so the total energy must be zero. At the surface: ½mv² + (−GMm/r) = 0. Rearranging: ½mv² = GMm/r, so v² = 2GM/r and v_esc = √(2GM/r), independent of the object's mass.\n(c) No. Escape velocity is the launch speed needed by an unpowered projectile to escape Earth's gravity completely. The falcon only needs to reach space (an altitude, not infinite distance), and if it is powered, its engine keeps doing work on it, so it can rise at any speed without ever reaching escape velocity.", [
    "(a) Uses W = mg with m = 0.500 kg.",
    "(a) W = 4.9 N.",
    "(b) States that to just escape, total energy at infinity is zero (K = 0 and U = 0).",
    "(b) Equates ½mv² with GMm/r at the surface.",
    "(b) Rearranges to v_esc = √(2GM/r).",
    "(c) States no, the falcon does not need escape velocity.",
    "(c) Justifies: escape velocity applies to an unpowered projectile leaving the field completely; a powered launch to space only needs to reach an altitude.",
  ]),
  s(56, "By Kepler's third law T²/r³ should be the same for both planets of the same star. Dra: 15²/9³ = 225/729 = 0.31. Groo: 20²/12³ = 400/1728 = 0.23. The ratios differ, so the planets do not orbit in accordance with Kepler's third law (the units do not matter, as long as they are the same for both planets).", [
    "States Kepler's third law: T²/r³ (or r³/T²) is constant for planets orbiting the same star.",
    "Calculates both ratios: Dra 0.31 and Groo 0.23.",
    "Concludes that the ratios differ, so the planets do not obey Kepler's third law.",
  ]),
  s(57, "(a) τ = rF, so F = τ/r = 5.0 / 0.45 ≈ 11 N.\n(b) τ = rF sin θ = 0.45 × 11.1 × sin 75° ≈ 4.8 N m.\n(c) As the engines fire and the spaceship moves to a higher orbit, the engines do work on it. Its gravitational potential energy increases (less negative) as it gets farther from Earth. In the new, higher circular orbit its orbital speed is lower, so its kinetic energy is less than before, but the total energy (−GMm/2r) has increased.\n(d) Orbital velocity is the speed needed to stay in a circular orbit at radius r, where gravity provides the centripetal force: v_orb = √(GM/r). Escape velocity is the minimum speed needed at a distance r to escape the gravitational field completely with no further propulsion (total energy zero): v_esc = √(2GM/r). At the same radius v_esc = √2 × v_orb; both depend only on the central mass and r, not on the mass of the object.", [
    "(a) Uses τ = rF with r = 0.45 m.",
    "(a) F ≈ 11 N.",
    "(b) Uses τ = rF sin θ with θ = 75°.",
    "(b) τ ≈ 4.8 N m.",
    "(c) Gravitational potential energy increases as the spaceship moves to a higher orbit.",
    "(c) Kinetic energy (orbital speed) is lower in the higher orbit; the engines' work increases the total energy.",
    "(d) Defines orbital velocity: v_orb = √(GM/r), gravity providing the centripetal force.",
    "(d) Defines escape velocity: v_esc = √(2GM/r), total energy zero.",
    "(d) Distinguishes them: escape velocity is √2 times the orbital velocity at the same radius.",
    "(d) Notes both depend on the central mass and r, not on the object's mass (or another valid distinction).",
  ]),
  s(58, "(a)(i) Planetary orbits are ellipses, so the distance from the Sun varies; the law uses the average (semi-major axis).\n(ii) Gravitational force (gravity).\n(iii) F = GM_S m/R².\n(iv) For a circular orbit the gravitational force provides the centripetal force: GM_S m/R² = mv²/R. The speed is v = 2πR/T, so GM_S m/R² = m(2πR/T)²/R = 4π²mR/T². Cancelling m and rearranging: T² = (4π²/GM_S)R³, so K = 4π²/GM_S.\n(b)(i) The gravitational field of Jupiter at Ganymede provides its centripetal acceleration: g = 4π²r/T² = 4π² × 1.1 × 10⁹ / (6.2 × 10⁵)² ≈ 0.11 N kg⁻¹ ≈ 0.1 N kg⁻¹.\n(ii) g = GM/r², so M = gr²/G = 0.113 × (1.1 × 10⁹)² / 6.67 × 10⁻¹¹ ≈ 2.0 × 10²⁷ kg (or M = 4π²r³/GT²).", [
    "(a)(i) Orbits are elliptical, so the orbital radius varies.",
    "(a)(ii) Gravitational force.",
    "(a)(iii) F = GM_S m/R².",
    "(a)(iv) Equates the gravitational force with the centripetal force.",
    "(a)(iv) Uses v = 2πR/T (or ω = 2π/T).",
    "(a)(iv) Substitutes and simplifies to T² = (4π²/GM_S)R³.",
    "(a)(iv) Identifies K = 4π²/GM_S.",
    "(b)(i) Uses g = a = 4π²r/T² (field strength equals centripetal acceleration).",
    "(b)(i) Obtains ≈ 0.11 N kg⁻¹.",
    "(b)(ii) Uses g = GM/r² (or Kepler's third law).",
    "(b)(ii) Correct substitution.",
    "(b)(ii) M ≈ 2 × 10²⁷ kg.",
  ]),
  s(59, "(a) The gravitational force of Saturn provides the centripetal force on the particle: GMm/R² = mv²/R. Cancelling m and one R gives GM = Rv².\n(b) R = 2.72 × 10⁸ / 2 = 1.36 × 10⁸ m. v = √(GM/R) = √(6.67 × 10⁻¹¹ × 5.69 × 10²⁶ / 1.36 × 10⁸) ≈ 1.67 × 10⁴ m s⁻¹. T = 2πR/v = 2π × 1.36 × 10⁸ / 1.67 × 10⁴ ≈ 5.1 × 10⁴ s.\n(c) Escape speed is the minimum launch speed for an object to escape the planet's gravitational field completely (reach infinity) with no further propulsion.\n(d) At the surface, g = GM/R², so GM = gR². To escape, the total energy must be zero: ½mv_es² − GMm/R = 0, so v_es² = 2GM/R = 2gR²/R = 2gR and v_es = √(2gR). Assumption: no air resistance (no atmosphere), or the planet is a uniform sphere with no other bodies' gravity acting.\n(e) v_es = √(2 × 1.6 × 1.7 × 10⁶) ≈ 2.3 × 10³ m s⁻¹.", [
    "(a) The gravitational force provides the centripetal force: GMm/R² = mv²/R.",
    "(a) Simplifies to GM = Rv².",
    "(b) Uses the radius (half the diameter), 1.36 × 10⁸ m.",
    "(b) Finds v ≈ 1.67 × 10⁴ m s⁻¹ (or uses T² = 4π²R³/GM).",
    "(b) T ≈ 5.1 × 10⁴ s.",
    "(c) Minimum speed needed to escape the gravitational field completely without further propulsion.",
    "(d) Uses g = GM/R² to write GM = gR².",
    "(d) Sets the total energy to zero at escape: ½mv² = GMm/R.",
    "(d) Combines to v_es = √(2gR).",
    "(d) States an assumption (no air resistance / no other gravitational forces / spherical planet).",
    "(e) Substitutes R = 1.7 × 10⁶ m and g = 1.6 m s⁻².",
    "(e) v_es ≈ 2.3 × 10³ m s⁻¹.",
  ]),
  s(60, "(a) F = GMm/r² = 6.67 × 10⁻¹¹ × 1.90 × 10²⁷ × 1500 / (2.0 × 10⁸)² ≈ 4.8 × 10³ N. (From the graph: g ≈ 3.2 N kg⁻¹ at 2.0 × 10⁸ m, so F = mg ≈ 4.8 × 10³ N.)\n(b) The area under the g–r graph between 1.0 × 10⁸ m and 2.0 × 10⁸ m is the change in potential energy per kilogram, ≈ 6.3 × 10⁸ J kg⁻¹ (equivalently GM(1/r₁ − 1/r₂)). ΔU = m × area = 1500 × 6.3 × 10⁸ ≈ 9.5 × 10¹¹ J (it decreases as Juno moves closer).\n(c) T = 2π√(r³/GM) = 2π√((6.70 × 10⁸)³ / (6.67 × 10⁻¹¹ × 1.90 × 10²⁷)) ≈ 3.06 × 10⁵ s (about 3.5 days).", [
    "(a) Uses F = GMm/r² (or F = mg with g read from the graph).",
    "(a) F ≈ 4.8 × 10³ N.",
    "(b) Recognises that the area under the g–r graph gives the change in potential energy per unit mass.",
    "(b) Estimates the area (≈ 6.3 × 10⁸ J kg⁻¹) or calculates GM(1/r₁ − 1/r₂).",
    "(b) |ΔU| ≈ 9.5 × 10¹¹ J (accept 9–10 × 10¹¹ J from the graph).",
    "(c) Uses Kepler's third law T² = 4π²r³/GM.",
    "(c) Correct substitution with r = 6.70 × 10⁸ m.",
    "(c) T ≈ 3.1 × 10⁵ s.",
  ]),
  s(61, "(a) r₁ = 6.371 × 10⁶ + 4.0 × 10⁵ = 6.771 × 10⁶ m; r₂ = 6.671 × 10⁶ m. ΔU = −GMm/r₂ − (−GMm/r₁) = GMm(1/r₁ − 1/r₂) = 6.67 × 10⁻¹¹ × 6.0 × 10²⁴ × 3000 × (1/6.771 × 10⁶ − 1/6.671 × 10⁶) ≈ −2.7 × 10⁹ J (a decrease).\n(b) The speed increases. Firing the retro rockets briefly removes a little energy, so the satellite falls inwards. As it falls, gravity does work on it: gravitational potential energy (−2.7 × 10⁹ J) is converted into kinetic energy, so it speeds up. In the lower circular orbit its total energy (−GMm/2r) is lower, but its kinetic energy GMm/2r is greater: the speed in the new orbit is √(GM/r) ≈ 7.7 × 10³ m s⁻¹, more than the original 7668 m s⁻¹.", [
    "(a) Uses U = −GMm/r with radii R_E + altitude for both orbits.",
    "(a) Correct substitution.",
    "(a) ΔU ≈ −2.7 × 10⁹ J (a decrease).",
    "(b) States the speed increases in the lower orbit.",
    "(b) Explains with energy conservation: the loss of gravitational potential energy as it falls is converted into kinetic energy.",
    "(b) Notes total energy decreased only slightly (from the rockets), while K = GMm/2r is larger at smaller r.",
  ]),
  s(62, "Both masses start from the same height and fall to the same surface, so each loses the same gravitational potential energy (same mass and same change in r), which is converted into kinetic energy (no atmosphere, so no losses). m₂ starts at rest, so its impact kinetic energy equals only the potential energy lost. m₁ already has kinetic energy from its horizontal speed, so its impact kinetic energy is greater: it hits with a greater speed, at an angle to the surface, whereas m₂ hits travelling straight down.", [
    "Both lose the same gravitational potential energy, converted to kinetic energy (conservation of energy, no air resistance).",
    "m₁ has initial kinetic energy, so its impact speed is greater than m₂'s.",
    "Compares directions: m₁ strikes at an angle (with a horizontal component); m₂ strikes vertically.",
  ]),
  s(63, "(a) On the line between the planet and the moon, much closer to the moon (where the satellite path passes near the moon), at the point where the gravitational pulls of the planet and the moon are equal and opposite.\n(b) Useful: it shows how the gravitational force of the central body provides the centripetal force that keeps the satellite in orbit, and how the gravity of two bodies combines, allowing paths to be predicted and planned. Limitations: it is not to scale and two-dimensional; it ignores other influences (the Sun, other moons, drag) and the movement of the moon during the journey, so it cannot give exact positions or speeds.", [
    "(a) The point between the planet and moon (closer to the moon) where their gravitational forces balance.",
    "(b) Describes a valid use (e.g. shows gravity providing centripetal force / how paths are planned).",
    "(b) Describes a valid limitation (e.g. not to scale, ignores other bodies or the moon's motion).",
  ]),
  s(64, "(a) Geostationary period T = 24 h = 86 400 s. r = (GMT²/4π²)^(1/3) = (6.67 × 10⁻¹¹ × 6.0 × 10²⁴ × 86 400² / 4π²)^(1/3) ≈ 4.23 × 10⁷ m. v = 2πr/T = √(GM/r) ≈ 3.08 × 10³ m s⁻¹.\n(b) ΔU = GMm(1/r_A − 1/r_B) = 6.67 × 10⁻¹¹ × 6.0 × 10²⁴ × 975 × (1/5.5 × 10⁷ − 1/4.23 × 10⁷) ≈ −2.1 × 10⁹ J (a decrease).\n(c) With no air resistance and no thrust, gravity is the only force, so the total mechanical energy is conserved: the decrease in gravitational potential energy from A to B equals the increase in kinetic energy. (To then stay in the circular geostationary orbit at B its speed would need adjusting.)\n(d) Conservation of energy from B (r = 4.23 × 10⁷ m, v = 2.5 × 10³ m s⁻¹) to C (r = 6.371 × 10⁶ m): ½v_C² = ½v_B² + GM(1/r_E − 1/r_B), so v_C² = (2.5 × 10³)² + 2 × 6.67 × 10⁻¹¹ × 6.0 × 10²⁴ × (1/6.371 × 10⁶ − 1/4.23 × 10⁷) and v_C ≈ 1.06 × 10⁴ m s⁻¹.", [
    "(a) Uses the geostationary period (24 h in seconds) in Kepler's third law.",
    "(a) Finds r ≈ 4.2 × 10⁷ m.",
    "(a) v ≈ 3.1 × 10³ m s⁻¹.",
    "(b) Uses ΔU = GMm(1/r_A − 1/r_B) (U = −GMm/r at both points).",
    "(b) ΔU ≈ −2.1 × 10⁹ J.",
    "(c) States that the total mechanical energy stays constant (only gravity acts, no air resistance).",
    "(c) Explains that the loss of U equals the gain in K.",
    "(d) Applies conservation of energy between B and C with U = −GMm/r.",
    "(d) v ≈ 1.06 × 10⁴ m s⁻¹.",
  ]),
  s(65, "(a) To escape, the total energy at launch must be at least zero: K_A ≥ GMm/r_E. Here K_A = (5/7)GMm/r_E is less than GMm/r_E, so the total energy is negative, (5/7 − 1)GMm/r_E = −(2/7)GMm/r_E: the shuttle is bound to Earth and cannot escape.\n(b) In a circular orbit gravity provides the centripetal force: GMm/R² = mv²/R, so mv² = GMm/R and K = ½mv² = GMm/2R. With U = −GMm/R: E_total = K + U = GMm/2R − GMm/R = −GMm/2R.\n(c) Conservation of energy: E at A = E at B. (5/7)GMm/r_E − GMm/r_E = −GMm/2R, so −2/(7r_E) = −1/(2R), giving R = 7r_E/4 (= 1.75 r_E).", [
    "(a) States the escape condition: K ≥ GMm/r_E (total energy ≥ 0).",
    "(a) Shows K_A < GMm/r_E so the total energy is negative and the shuttle is bound.",
    "(b) Equates gravitational and centripetal force to find K = GMm/2R.",
    "(b) Uses U = −GMm/R.",
    "(b) Adds them: E_total = −GMm/2R.",
    "(c) Sets the total energy at A equal to the total energy at B.",
    "(c) Correct algebra: (5/7 − 1)/r_E = −1/(2R).",
    "(c) R = 7r_E/4.",
  ]),
  s(66, "(a) F = Gm₁m₂/d² = 6.67 × 10⁻¹¹ × 26.5 × 26.5 / 11.0² ≈ 3.9 × 10⁻¹⁰ N.\n(b) The force follows an inverse-square curve: it decreases rapidly at first and then more slowly as the separation increases, approaching zero but never reaching it. At 2d the force is F/4 ≈ 9.7 × 10⁻¹¹ N; at 4d it is F/16 ≈ 2.4 × 10⁻¹¹ N.", [
    "(a) Uses F = Gm₁m₂/d².",
    "(a) F ≈ 3.9 × 10⁻¹⁰ N.",
    "(b) Describes an inverse-square curve (decreasing, approaching zero).",
    "(b) Gives F/4 ≈ 9.7 × 10⁻¹¹ N at 2d and F/16 ≈ 2.4 × 10⁻¹¹ N at 4d.",
  ]),
  s(67, "(a) T = 0.942 × 86 400 = 8.14 × 10⁴ s. M = 4π²r³/(GT²) = 4π² × (1.86 × 10⁸)³ / (6.67 × 10⁻¹¹ × (8.14 × 10⁴)²) ≈ 5.7 × 10²⁶ kg.\n(b) Kepler's third law: T_D = T_M (r_D/r_M)^(3/2) = 0.942 × (3.78/1.86)^(3/2) ≈ 2.73 Earth days.\n(c) Velocity is a vector. Even if Dione's orbit is circular and its speed constant, its direction of motion changes continuously because Saturn's gravitational force acts towards the centre, perpendicular to the velocity, providing the centripetal force. So the velocity changes (the moon accelerates towards Saturn) while the speed stays the same. (If the orbit is slightly elliptical, the speed also varies, faster when closer.)", [
    "(a) Uses Kepler's third law with T in seconds.",
    "(a) M ≈ 5.7 × 10²⁶ kg.",
    "(b) Applies T² ∝ r³ (or uses Saturn's mass).",
    "(b) T ≈ 2.7 Earth days.",
    "(c) Velocity is a vector, so a change in direction is a change in velocity.",
    "(c) Saturn's gravitational force acts towards the centre (perpendicular to the velocity), providing the centripetal force.",
    "(c) So the direction changes continuously while the speed is constant (centripetal acceleration).",
  ]),
  s(68, "(a) r = 6.371 × 10⁶ + 3.000 × 10⁵ = 6.671 × 10⁶ m. g = GM/r² = 6.67 × 10⁻¹¹ × 6.0 × 10²⁴ / (6.671 × 10⁶)² ≈ 9.0 m s⁻².\n(b) T = 94.7 × 60 = 5682 s. r = (GMT²/4π²)^(1/3) ≈ 6.89 × 10⁶ m.\n(c) v_esc = √(2GM/r) = √(2 × 6.67 × 10⁻¹¹ × 6.0 × 10²⁴ / 6.89 × 10⁶) ≈ 1.08 × 10⁴ m s⁻¹.", [
    "(a) Uses g = GM/r² with r = R_E + 300 km.",
    "(a) g ≈ 9.0 m s⁻².",
    "(b) Uses Kepler's third law with T in seconds.",
    "(b) r ≈ 6.89 × 10⁶ m.",
    "(c) Uses v_esc = √(2GM/r) with the ISS's orbital radius.",
    "(c) v ≈ 1.08 × 10⁴ m s⁻¹.",
  ]),
  s(69, "(a) E = −GMm/2r = −6.67 × 10⁻¹¹ × 6.0 × 10²⁴ × 50 / (2 × 1.0 × 10⁷) ≈ −1.0 × 10⁹ J.\n(b) Friction does negative work, so the satellite's total energy decreases (becomes more negative). Since E = −GMm/2r, its orbital radius decreases: it gradually spirals to lower orbits (orbital decay). In a lower orbit its speed v = √(GM/r) is greater, so its kinetic energy increases, while its gravitational potential energy decreases by twice as much. As it descends into denser air the drag increases, and it eventually burns up or falls to Earth.", [
    "(a) Uses E = −GMm/2r with r = 1.0 × 10⁷ m.",
    "(a) E ≈ −1.0 × 10⁹ J.",
    "(b) Friction removes energy, so the total energy decreases and the orbit decays to a smaller radius.",
    "(b) In the lower orbit the speed (and kinetic energy) increases while the potential energy decreases.",
    "(b) Increasing drag leads to re-entry / the satellite eventually falls to Earth.",
  ]),
  s(70, "(a) T = 1 h 40 min = 6000 s. r = (GMT²/4π²)^(1/3) = (6.67 × 10⁻¹¹ × 6.0 × 10²⁴ × 6000² / 4π²)^(1/3) ≈ 7.15 × 10⁶ m. Altitude = r − R_E = 7.15 × 10⁶ − 6.371 × 10⁶ ≈ 7.8 × 10² km.\n(b) Any two, e.g.: it is close to Earth, so it can take high-resolution images or make detailed measurements; it passes over many regions as Earth turns beneath it (global coverage, e.g. polar orbit); short signal delay; cheaper to launch than a geostationary satellite; it is above most of the atmosphere, so drag is small.", [
    "(a) Uses Kepler's third law with T = 6000 s.",
    "(a) Finds r ≈ 7.15 × 10⁶ m.",
    "(a) Subtracts Earth's radius: altitude ≈ 780 km.",
    "(b) First benefit.",
    "(b) Second benefit.",
  ]),
  s(71, "Gravity is a conservative force, so the total mechanical energy of an object moving only under gravity is conserved: K + U = constant, with U = −GMm/r (zero at infinity). An object launched at distance r with speed v starts with E = ½mv² − GMm/r. As it moves away, kinetic energy is converted into gravitational potential energy. To escape completely it must reach infinite distance, where U = 0; the minimum speed is the one for which it arrives there with zero kinetic energy, so the total energy is zero: ½mv² − GMm/r = 0. Rearranging, ½mv² = GMm/r, v² = 2GM/r and v = √(2GM/r). The object's mass cancels, so the escape velocity depends only on the planet's mass and the distance r.", [
    "States conservation of mechanical energy: K + U is constant (only gravity acts).",
    "Uses U = −GMm/r, with U = 0 at infinity.",
    "Explains that escape means reaching infinity with (at least) zero kinetic energy, so the total energy is zero.",
    "Sets ½mv² = GMm/r.",
    "Rearranges to v = √(2GM/r) (and notes it is independent of m).",
  ]),
  s(72, "(a) M = 4π²r³/(GT²) with r = 1.00 × 10⁵ m and T = 27 × 3600 = 9.72 × 10⁴ s: M = 4π² × (1.00 × 10⁵)³ / (6.67 × 10⁻¹¹ × (9.72 × 10⁴)²) ≈ 6.3 × 10¹⁶ kg.\n(b) Kepler's third law with Earth (T = 1 year, r = 150 million km): r_J = 150 × 10⁶ × 12^(2/3) ≈ 786 × 10⁶ km. The minimum displacement is when Earth and Jupiter are on the same side of the Sun in line: 786 − 150 ≈ 636 million km (≈ 6.4 × 10¹¹ m).", [
    "(a) Uses Kepler's third law with r in metres and T in seconds.",
    "(a) M ≈ 6.3 × 10¹⁶ kg.",
    "(b) Uses Kepler's third law to find Jupiter's orbital radius ≈ 7.9 × 10⁸ km.",
    "(b) Minimum displacement ≈ 6.4 × 10⁸ km (radii subtracted, planets aligned on the same side).",
  ]),
  s(73, "(a) To just escape, the kinetic energy at distance r must equal the magnitude of the gravitational potential energy: ½mv² = GMm/r. Rearranging: v = √(2GM/r).\n(b) v = 2 m s⁻¹ is the escape velocity at distance r: r = 2GM/v² = 2 × 6.67 × 10⁻¹¹ × 6.0 × 10²⁴ / 2² ≈ 2.0 × 10¹⁴ m.", [
    "(a) Sets ½mv² = GMm/r.",
    "(a) Obtains v = √(2GM/r).",
    "(b) Rearranges to r = 2GM/v².",
    "(b) r ≈ 2.0 × 10¹⁴ m.",
  ]),
  s(74, "(a) U = −GMm/R_E = −6.67 × 10⁻¹¹ × 6.0 × 10²⁴ × 4000 / 6.371 × 10⁶ ≈ −2.5 × 10¹¹ J.\n(b) r = 6.371 × 10⁶ + 2.5 × 10⁵ = 6.621 × 10⁶ m. U = −GMm/r ≈ −2.4 × 10¹¹ J.\n(c) In a circular orbit K = GMm/2r = 6.67 × 10⁻¹¹ × 6.0 × 10²⁴ × 4000 / (2 × 6.621 × 10⁶) ≈ 1.2 × 10¹¹ J.", [
    "(a) U ≈ −2.5 × 10¹¹ J (U = −GMm/R_E).",
    "(b) U ≈ −2.4 × 10¹¹ J (r = R_E + 250 km).",
    "(c) Uses K = ½mv² with v = √(GM/r), i.e. K = GMm/2r.",
    "(c) K ≈ 1.2 × 10¹¹ J.",
  ]),
  s(75, "Kepler's third law for bodies orbiting the Sun: r³/T² is constant. Using Earth (T = 1 year, r = 150 million km): r_H = 150 × 10⁶ × 75^(2/3) ≈ 150 × 10⁶ × 17.8 ≈ 2.7 × 10⁹ km (2.7 × 10¹² m).", [
    "Applies Kepler's third law using Earth's orbit for comparison.",
    "r ≈ 2.7 × 10⁹ km.",
  ]),
  s(76, "(a) F = Gm₁m₂/r² = 6.67 × 10⁻¹¹ × 0.250 × 0.070 / (1000)² ≈ 1.2 × 10⁻¹⁸ N.\n(b) By Newton's third law both meteors feel the same size force, but a = F/m, so the 70 g meteor accelerates 250/70 ≈ 3.6 times more than the 250 g meteor (a ≈ 1.7 × 10⁻¹⁷ m s⁻² vs 4.7 × 10⁻¹⁸ m s⁻² at 1 km). As they come together, r decreases and F ∝ 1/r² increases, so both accelerations increase (e.g. halving the distance makes them four times larger).", [
    "(a) F ≈ 1.2 × 10⁻¹⁸ N.",
    "(b) Same force on both (Newton's third law) but a = F/m, so the lighter meteor has the larger acceleration (≈ 3.6 times).",
    "(b) Both accelerations increase as they approach because F ∝ 1/r².",
  ]),
  s(77, "(a) Gravity provides the centripetal force: GMm/r² = 4π²mr/T², so r³ = GMT²/4π² = 6.67 × 10⁻¹¹ × 6.0 × 10²⁴ × (86 400)² / 4π², giving r ≈ 4.2 × 10⁷ m.\n(b) ΔU = U_orbit − U_surface = −GMm/r + GMm/R = GMm(1/R − 1/r) = 6.67 × 10⁻¹¹ × 6.0 × 10²⁴ × 650 × (1/6.4 × 10⁶ − 1/4.2 × 10⁷) ≈ 3.4 × 10¹⁰ J.", [
    "(a) Equates gravitational and centripetal force (or uses Kepler's third law).",
    "(a) Substitutes T = 86 400 s to show r ≈ 4.2 × 10⁷ m.",
    "(b) Uses U = −GMm/r at both the surface and the orbit (not mgh).",
    "(b) Correct substitution of both radii.",
    "(b) ΔU ≈ 3.4 × 10¹⁰ J.",
  ]),
  s(78, "(a) T = 2π√(r³/GM) = 2π√((6.671 × 10⁶)³ / (6.67 × 10⁻¹¹ × 6.0 × 10²⁴)) ≈ 5.4 × 10³ s (about 90 minutes).\n(b) v = 2πr/T = √(GM/r) ≈ 7.7 × 10³ m s⁻¹.\n(c) Gravity provides the centripetal force: GMm/r² = 4π²mr/T². The satellite's mass m appears on both sides and cancels, giving T² = 4π²r³/GM. The period depends only on Earth's mass and the orbital radius. A 1000 kg satellite feels ten times the gravitational force, but needs ten times the centripetal force for the same motion, so its acceleration, speed and period are the same.", [
    "(a) Uses T² = 4π²r³/GM.",
    "(a) T ≈ 5.4 × 10³ s.",
    "(b) Uses v = 2πr/T or v = √(GM/r).",
    "(b) v ≈ 7.7 × 10³ m s⁻¹.",
    "(c) Equates the gravitational force with the centripetal force.",
    "(c) Shows the satellite mass cancels: T² = 4π²r³/GM.",
    "(c) Concludes T depends only on M and r (larger mass means proportionally larger force, same acceleration).",
  ]),
  s(79, "Being close to Earth (a few hundred km) has advantages that outweigh the drawbacks: they can take high-resolution images and make detailed measurements (Earth observation, mapping, weather, surveillance); their short period means they pass over much of the Earth's surface each day, especially in polar orbits; signals travel a short distance, so there is little delay and weaker transmitters are needed; and they are cheaper and easier to launch, replace and service (e.g. the ISS, satellite constellations).", [
    "Gives a valid advantage of being close to Earth (e.g. high-resolution imaging, short signal delay).",
    "Gives a second valid advantage (e.g. global coverage from a short period, cheaper launch and replacement).",
  ]),
  s(80, "Escape velocity is found from conservation of energy: to just escape, the kinetic energy at launch must equal the magnitude of the gravitational potential energy, ½mv² = GMm/r. Both the kinetic energy and the potential energy are proportional to the object's mass m, so m cancels, giving v = √(2GM/r): only the planet's mass and the distance from its centre matter. A more massive object needs more energy to escape, but that same speed gives it proportionally more kinetic energy.", [
    "Sets ½mv² = GMm/r (escape condition from energy conservation).",
    "Shows that m appears in both terms and cancels.",
    "Concludes v_esc = √(2GM/r) depends only on M and r (more massive objects need more energy, but have proportionally more kinetic energy).",
  ]),
  s(81, "P is the farthest point (apogee), so the satellite is slowest there. As it moves from P towards Earth, gravity has a component along its velocity: it does positive work, converting gravitational potential energy into kinetic energy, so the satellite speeds up, reaching its maximum speed at perigee (closest point). It then slows down again as it moves back out to P, as kinetic energy is converted back into potential energy. Total energy is conserved, and by Kepler's second law it sweeps out equal areas in equal times, so it moves slowly for most of the 12-hour orbit near P (giving long coverage of high latitudes). The direction of the velocity also changes continuously, always along the tangent to the orbit.", [
    "Speed is lowest at P (apogee) and highest at perigee (closest point).",
    "Explains with energy conservation (U converted to K as it falls in, and back) or Kepler's second law.",
    "Notes the velocity's direction changes continuously (tangential), or links the slow motion near P to long coverage.",
  ]),
  s(82, "(a) Distance between centres r = 3.84 × 10⁸ + 6.371 × 10⁶ = 3.90 × 10⁸ m. F = GMm/r² = 6.67 × 10⁻¹¹ × 6.0 × 10²⁴ × 7.35 × 10²² / (3.90 × 10⁸)² ≈ 1.93 × 10²⁰ N.\n(b) Work to move the rock (from rest to rest) = ΔU = GMm(1/r₁ − 1/r₂). From the first move: GMm(1/1.0 × 10⁷ − 1/2.0 × 10⁷) = GMm × 5.0 × 10⁻⁸ = 1.0 × 10⁶ J, so GMm = 2.0 × 10¹³ J m. Second move: W = 2.0 × 10¹³ × (1/2.0 × 10⁷ − 1/8.0 × 10⁷) = 2.0 × 10¹³ × 3.75 × 10⁻⁸ = 7.5 × 10⁵ J (0.75 MJ).", [
    "(a) Uses F = GMm/r² with the distance between centres (adds Earth's radius).",
    "(a) Correct substitution giving ≈ 1.93 × 10²⁰ N.",
    "(b) Recognises the work equals the change in gravitational potential energy, GMm(1/r₁ − 1/r₂).",
    "(b) Uses the first move to find GMm = 2.0 × 10¹³ J m.",
    "(b) W = 7.5 × 10⁵ J.",
  ]),
  s(83, "(a) Kepler's second law: the line joining the planet to the Sun sweeps out equal areas in equal times. When the planet is closer to the Sun the line is shorter, so it must move a greater distance along the orbit in the same time: the planet moves fastest at its closest point (perihelion) and slowest at its farthest point (aphelion). (Equivalently, kinetic energy increases as gravitational potential energy decreases.)\n(b) v = 2πr/T = 2π × 1.5 × 10¹¹ / (365 × 24 × 3600) ≈ 3.0 × 10⁴ m s⁻¹.", [
    "(a) States Kepler's second law (equal areas in equal times).",
    "(a) Speed is greatest closest to the Sun and least farthest away.",
    "(b) v ≈ 3.0 × 10⁴ m s⁻¹.",
  ]),
  s(84, "The orbital velocity depends only on Earth's mass and the orbital radius (r = R_E + height), not on the satellite. Gravity provides the centripetal force: GMm/r² = mv²/r, so v = √(GM/r). The LEO satellite (Iridium) has the smallest radius (≈ 7850 km) so it has the largest velocity (7.13 km/s); the MEO (New ICO, r ≈ 16 600 km) is slower (4.90 km/s); the GEO (Intelsat, r ≈ 42 200 km) is slowest (3.07 km/s). Because v ∝ 1/√r, the GEO radius is about 5.4 times the LEO radius, giving a speed about 2.3 times smaller, as in the table. (A check: √(GM/r) = √(4.0 × 10¹⁴ / 4.22 × 10⁷) ≈ 3.08 km/s for GEO.)", [
    "Gravity provides the centripetal force: GMm/r² = mv²/r.",
    "Derives v = √(GM/r): velocity depends on the orbital radius (and Earth's mass), not the satellite's mass.",
    "Uses r = R_E + orbital height.",
    "Relates the data: larger radius gives a smaller orbital velocity (LEO fastest, GEO slowest), with supporting calculation or proportional reasoning.",
  ]),
  s(85, "Newton's law of universal gravitation gives the force on the satellite, F = GMm/r². In a circular orbit this provides the centripetal force: GMm/r² = mv²/r. Multiplying both sides by r: mv² = GMm/r. So the kinetic energy K = ½mv² = GMm/2r.", [
    "States F = GMm/r² and equates it with the centripetal force mv²/r.",
    "Rearranges to mv² = GMm/r.",
    "Substitutes into K = ½mv² to obtain K = GMm/2r.",
  ]),
  s(86, "Mechanical energy is conserved: ½mv₁² − GMm/R = ½mv² − GMm/2R. Cancelling m: v² = v₁² − 2GM/R + GM/R = v₁² − GM/R. With R = 6.371 × 10⁶ m: GM/R = 6.67 × 10⁻¹¹ × 6.0 × 10²⁴ / 6.371 × 10⁶ ≈ 6.28 × 10⁷ m² s⁻². v² = 8200² − 6.28 × 10⁷ ≈ 4.4 × 10⁶, so v ≈ 2.1 × 10³ m s⁻¹.", [
    "Writes conservation of energy with U = −GMm/r at R and at 2R.",
    "Simplifies to v² = v₁² − GM/R (mass cancels).",
    "Substitutes Earth's mass and radius correctly.",
    "v ≈ 2.1 × 10³ m s⁻¹.",
  ]),
  s(87, "With r_A = r and r_B = 3r: E = −GMm/(r + 3r) = −GMm/4r. Total energy is the same at every point, so K = E − U. At A: K_A = −GMm/4r − (−GMm/r) = 3GMm/4r. At B: K_B = −GMm/4r − (−GMm/3r) = GMm/12r. Ratio: K_A/K_B = (3/4) ÷ (1/12) = 9.", [
    "Substitutes r_A = r and r_B = 3r: E = −GMm/4r.",
    "Uses K = E − U with U = −GMm/r_A and U = −GMm/r_B.",
    "Finds K_A = 3GMm/4r and K_B = GMm/12r.",
    "K_A/K_B = 9.",
  ]),
  s(88, "(a) For a circular orbit the gravitational force provides the centripetal force: GMm/r² = mv²/r, so mv² = GMm/r and K = ½mv² = GMm/2r. Since U = −GMm/r, K = −U/2. Therefore E = K + U = −U/2 + U = U/2.\n(b) Over one complete orbit the net work done by gravity is zero for both satellites, because each returns to its starting point with the same speed: gravity is a conservative force and the changes in U and K add to zero. For the circular orbit the work is zero at every instant, since the force is always perpendicular to the velocity and the speed and r never change. For the elliptical orbit, gravity does negative work as the satellite moves out from P to A (it slows down, gaining U) and an equal amount of positive work as it moves back from A to P (it speeds up), so the total is zero.", [
    "(a) Equates gravitational and centripetal force: GMm/r² = mv²/r.",
    "(a) Shows K = GMm/2r = −U/2.",
    "(a) Adds to get E = K + U = U/2.",
    "(b) Net work over one orbit is zero for both satellites (same position and speed after a full orbit; gravity is conservative).",
    "(b) Circular orbit: the force is always perpendicular to the velocity, so no work is done at any point.",
    "(b) Elliptical orbit: negative work moving away (P to A) and equal positive work returning (A to P) cancel.",
  ]),
  s(89, "(a) v² = GM/r, so M = v²r/G = (1400)² × 5.5 × 10⁷ / 6.67 × 10⁻¹¹ ≈ 1.6 × 10²⁴ kg.\n(b) v_esc = √(2GM/r) = √2 × v_orb = √2 × 1400 ≈ 2.0 × 10³ m s⁻¹.", [
    "(a) Uses v = √(GM/r) (from gravity providing the centripetal force).",
    "(a) M ≈ 1.6 × 10²⁴ kg.",
    "(b) Uses v_esc = √(2GM/r) (= √2 × orbital velocity).",
    "(b) v_esc ≈ 2.0 × 10³ m s⁻¹.",
  ]),
  s(90, "The geostationary period is 24 h, so the low Earth satellite's period is 24/12 = 2.0 h = 7200 s. Kepler's third law: r = (GMT²/4π²)^(1/3) = (6.67 × 10⁻¹¹ × 6.0 × 10²⁴ × 7200² / 4π²)^(1/3) ≈ 8.07 × 10⁶ m. Altitude = 8.07 × 10⁶ − 6.371 × 10⁶ ≈ 1.7 × 10⁶ m (about 1700 km). (Equivalently, r = r_GEO × (1/12)^(2/3) = 4.23 × 10⁷ / 5.24.)", [
    "Finds the period: T = 24 h / 12 = 2 h = 7200 s.",
    "Uses Kepler's third law to find r ≈ 8.1 × 10⁶ m.",
    "Subtracts Earth's radius: altitude ≈ 1.7 × 10⁶ m.",
  ]),
];
